function shootBoss(power){if(isMap()){mapShoot(power);return}if(S.phase!=='boss'||B.state==='intro'||B.state==='phaseChange')return;const el=node('g');el.appendChild(node('path',{d:'M-15-7L20 0-15 7-6 0Z',fill:power>1?'#ffe0a1':'#9ef3da',stroke:'#effff0','stroke-width':1.5}));$('bossShots').appendChild(el);shots.push({el,x:dogX()+55,y:GROUND+S.y-78,power,life:1.8,dir:1,openAtLaunch:B.state==='open'});beep(620,.1,'triangle',.024)}
