function stepBoss(dt){if(isMap()){stepMapBoss(dt);return}if(!['boss','bossVictory'].includes(S.phase)||S.paused)return;const worldDt=S.phase==='boss'?tickLegend(dt):dt;B.t+=worldDt;B.elapsed+=worldDt;B.flash=Math.max(0,B.flash-dt);for(const k of['cool','dash','inv','toast','shake','comboTime','jumpBuffer','freedom'])S[k]=Math.max(0,S[k]-dt);updateDashMotion(dt);if(S.comboTime===0)S.combo=0;const wasAir=S.y<0;S.vy+=1600*dt;S.y+=S.vy*dt;if(S.y>=0){S.y=0;S.vy=0;S.jumps=0;if(wasAir){ripple(dogX());if(S.jumpBuffer>0)jumpCore()}}S.distance+=70*dt;updateFX(dt);
