// Wallet persistence is installed after all progression modules.
function awardCoins(amount,source='金币'){if(mapAward(amount))return;if(S.mode!=='play'||['dojo','tutorial'].includes(V.route)||V.finished)return;amount=Math.max(0,Math.floor(amount));wallet.balance=Math.min(1000000000,wallet.balance+amount);S.runCoins+=amount;saveWallet();if(amount>1)toast(source+' +'+amount,'#ffe6a1')}
function dogX(){return DOGX+S.offset}
function dashCooldown(){const sk=playSkill();if(sk==='chrono'&&S.chrono>0)return 1.4;if(sk==='rail')return S.phase==='boss'?1.6:2.6;return S.phase==='boss'?(sk==='wind'?1.2:1.35):S.freedom>0?1.8:sk==='wind'?2.7:3.2}
function updateDashMotion(dt){const reach=playSkill()==='wind'?142:118;if(S.dash>0){const p=Math.min(1,(.57-S.dash)/.17);S.offset=reach*(1-Math.pow(1-p,3))}else S.offset=Math.max(0,S.offset-dt*(playSkill()==='wind'?355:310));if(S.dash>0&&!reduced){echoTick-=dt;if(echoTick<=0){echoTick=.065;emitEcho()}}dashEchoes=dashEchoes.filter(e=>{e.life-=dt;attr(e.el,'opacity',Math.max(0,e.life/.26)*.32);if(e.life<=0)e.el.remove();return e.life>0})}
function cleanClone(source){const copy=source.cloneNode(true);copy.removeAttribute('id');for(const n of copy.querySelectorAll('[id]'))n.removeAttribute('id');return copy}
function emitEcho(){if(dashEchoes.length>=4)dashEchoes.shift().el.remove();const g=node('g',{transform:`translate(${dogX()-15},${GROUND+S.y})`,opacity:.3,'pointer-events':'none'});g.appendChild(cleanClone($('dogBody')));$('dashEchoes').appendChild(g);dashEchoes.push({el:g,life:.26})}
function clearDashFX(){dashEchoes.forEach(e=>e.el.remove());dashEchoes=[];echoTick=0;S.offset=0}
function consumeShield(){if(S.guard<=0)return false;S.guard--;S.inv=1.4;toast('纸盾挡住了 / 完美路线保留','#bce9ff');puff(dogX()+15,GROUND+S.y-64,14,'#bce9ff');beep(520,.17,'triangle',.025);return true}
