function spawn(){if(V.route!=='story'){spawnVoyage();return}const chapters=[[['coffee',-54],['folder',0],['notice',-162],['folder',0],['coffee',-145],['notice',0],['pair',0],['coffee',-80],['notice',-162],['folder',0]], [['coffee',-145],['pair',0],['notice',-162],['coffee',-54],['folder',0],['notice',0],['coffee',-220],['pair',0]], [['pair',0],['coffee',-145],['notice',-162],['folder',0],['coffee',-54],['pair',0],['notice',-162],['coffee',-220]], [['coffee',-54],['folder',0],['coffee',-145],['notice',0],['coffee',-220],['pair',0],['coffee',-54]]];const list=chapters[S.chapter],index=S.spawnIndex++;let[type,height]=list[index%list.length];const next=list[(index+1)%list.length];S.safeGap=next[0]==='notice'&&next[1]<0?(type==='pair'?1.9:type==='folder'||type==='notice'?1.5:0):0;if(type==='pair'){spawnOne('folder');spawnOne('notice',0,(mobile?930:1400)+165)}else spawnOne(type,height);if(index%2===0){const base=mobile?930:1400,arc=[-52,-97,-126,-97,-52];for(let i=0;i<arc.length;i++)spawnOne('coin',arc[i],base+85+i*43)}}
function paintSkin(root,c,global=false){if(global){const stops=$('coatGrad').querySelectorAll('stop');stops.forEach((s,i)=>attr(s,'stop-color',c.coat[i]));set('dogHood','fill',c.hood);set('dogTrim','stroke',c.trim);set('dogPocket','fill',c.pocket);set('dogHem','fill',c.coat[1]);set('dogScarf','fill',c.scarf);set('dogScarfTail','fill',c.accent);const accessory=$('skinAccessory');accessory.replaceChildren();skinAccessory(accessory,c.id)}else{const body=root.querySelector('[data-part="coat"]');if(body)attr(body,'fill',c.coat[1]);for(const[part,key,attribute]of[['hood','hood','fill'],['trim','trim','stroke'],['pocket','pocket','fill'],['hem','pocket','fill'],['scarf','scarf','fill'],['scarfTail','accent','fill']]){const el=root.querySelector('[data-part="'+part+'"]');if(el)attr(el,attribute,c[key])}const a=root.querySelector('[data-part="accessory"]');if(a){a.replaceChildren();skinAccessory(a,c.id)}}}
