function applySkin(){const c=CATALOG.skins.find(c=>c.id===lookSkin())||CATALOG.skins[0];paintSkin($('dogBody'),c,true);attr($('dog'),'data-skin',c.id);attr($('dogBody'),'data-skin',c.id);set('dogCoat','fill','url(#coatGrad)');$('dogReflection').replaceChildren(cleanClone($('dogBody')));const reflection=$('dogReflection').firstElementChild;reflection.removeAttribute('transform')}
function toggleShop(force){if(hubOpen)toggleHub(false);if(voyagePanel)closeVoyagePanel();const next=typeof force==='boolean'?force:!shopOpen;if(next===shopOpen)return;if(next){shopWasPaused=S.paused;if(['running','boss','bossVictory'].includes(S.phase))pause(true);shopOpen=true;shopTab='skins';shopPage=0;buyConfirm='';detailId='';show('shopDetail',false);shopNotice='';shopLayout();renderShop();show('shopPanel',true);$('shopCloseBtn').focus()}else{shopOpen=false;detailId='';buyConfirm='';show('shopDetail',false);show('shopPanel',false);if(!shopWasPaused&&['running','boss','bossVictory'].includes(S.phase))pause(false);last=performance.now();$('shopBtn').focus()}render()}
function renderV4(){const x=dogX();if(['boss','bossVictory'].includes(S.phase)){pos('skillHud',mobile?26:28,mobile?120:126);pos('bossCallout',mobile?55:400,mobile?180:126)}else pos('skillHud',mobile?26:884,mobile?98:27);set('dogShadow','transform',`translate(${S.offset},0)`);set('dashWind','opacity',S.dash>0?.9:0);set('dashWind','transform',`translate(${S.offset},${S.y})`);set('dashNose','transform',`translate(${x+95},${GROUND+S.y-85}) scale(${S.dash>0?1:0})`);show('guardRing',S.guard>0&&['running','boss'].includes(S.phase));set('guardRing','transform',`translate(${x+12},${GROUND+S.y-65})`);text('coinText','金币 '+S.runCoins);text('walletLabel',shopOpen?'收起商店':'商店 · '+wallet.balance);text('equippedText',wallet.skill?(CATALOG.skills.find(c=>c.id===wallet.skill)?.name||''):'原装 / 无技能');set('riverBridge','transform',`translate(${-S.distance*.2%1800},0)`);set('riverShimmer','transform',`translate(${-S.distance*.07%180},0)`);set('riverBank','transform',`translate(${-S.distance*.08%180},0)`);show('coinHud',['running'].includes(S.phase)&&S.mode==='play');if(S.phase==='ending')text('ticketHint',S.mode==='play'?`本局金币 +${S.runCoins} · 钱包 ${wallet.balance} / 票根不上传数据`:'自动放映不赚金币 / 票根不上传数据')}
