for(let i=0;i<4;i++)bind('shopBuy'+i,()=>purchase(shopCards()[i]?.id));bind('shopBtn',()=>toggleShop());bind('shopCloseBtn',()=>toggleShop(false));bind('skinTab',()=>{shopTab='skins';shopPage=0;buyConfirm='';closeDetail();shopLayout();renderShop()});bind('skillTab',()=>{shopTab='skills';shopPage=0;buyConfirm='';closeDetail();shopLayout();renderShop()});$('shopPanel').addEventListener('pointerdown',e=>e.stopPropagation());$('shopPanel').addEventListener('click',e=>e.stopPropagation());window.addEventListener('keydown',e=>{if(e.key==='Escape'&&shopOpen){e.preventDefault();detailId?closeDetail():toggleShop(false)}});


// Four single-slot legends: real projectiles, orbit interception, whale sweep, local time-lock.
let legendBolts=[],legendEchoClock=0,skinTrails=[],skinTrailTick=0;const isLegend=()=>LEGEND_SKILLS.some(c=>c.id===playSkill());
function freeDuration(){return playSkill()==='leviathan'?4.4:playSkill()==='chrono'?2.4:3.8}
function resetLegend(){for(const b of legendBolts)b.el.remove();legendBolts=[];$('legendBolts').replaceChildren();legendEchoClock=0;skinTrailTick=0;skinTrails.forEach(p=>p.el.remove());skinTrails=[];$('skinTrails').replaceChildren()}
function tickSkinTrails(dt){const c=LEGEND_SKINS.find(c=>c.id===lookSkin());skinTrailTick-=dt;if(c&&!reduced&&skinTrailTick<=0&&skinTrails.length<8){skinTrailTick=S.dash>0?.09:.22;const x=dogX()-39,y=GROUND+(S.y<0?S.y-48:4),g=node('g',{transform:`translate(${x},${y})`,opacity:.45});const d=c.id==='dragon'?'M-17 0Q0-9 17 0M-12 5Q0-1 12 5':c.id==='neon'?'M-19-1H9M-11 5H19':c.id==='corona'?'M-10 4L-3-15L3-5L11-19L14 4Z':'M-10-4l10-11 10 11-10 6Z';g.appendChild(node('path',{d,fill:c.id==='corona'||c.id==='eclipse'?c.fx:'none',stroke:c.fx,'stroke-width':1.5}));$('skinTrails').appendChild(g);skinTrails.push({el:g,x,y,life:.55})}skinTrails=skinTrails.filter(p=>{p.life-=dt;p.x-=110*dt;attr(p.el,'transform',`translate(${p.x},${p.y})`);attr(p.el,'opacity',Math.max(0,p.life/.55)*.38);if(p.life<=0)p.el.remove();return p.life>0})}
function legendBurst(x,y,color='#bafbe3'){if(reduced)return;if(legendBolts.length>=28)return;const g=node('g',{transform:`translate(${x},${y})`,opacity:1});g.appendChild(node('circle',{r:15,fill:'none',stroke:color,'stroke-width':3}));g.appendChild(node('path',{d:'M-30 0H30M0-30V30M-20-20L20 20M-20 20L20-20',stroke:color,'stroke-width':1.5}));$('legendBolts').appendChild(g);legendBolts.push({el:g,x,y,life:.32,total:.32,kind:'burst'})}
function legendBreak(o,color='#b7fae4'){if(o.done||o.token||o.ghost||(o.armored&&S.freedom<=0))return;o.done=true;S.smashed++;combo();legendBurst(o.x,o.y-37,color);puff(o.x,o.y-37,4,color)}
function legendCollect(o){if(o.done)return;o.done=true;if(o.coin)awardCoins(voyageCoinValue());else{S.coffee++;extraCoffee();gainEnergy();combo()}puff(o.x,o.y-25,3,o.coin?'#ffe2a4':'#c1faec')}
function railShot(){const el=node('g');el.appendChild(node('path',{d:'M-120 0H8M-92-5l25 10 27-12 23 13 23-10',fill:'none',stroke:'#95f8ff','stroke-width':5,'stroke-linecap':'round'}));el.appendChild(node('path',{d:'M-90 0H15',stroke:'#fff9df','stroke-width':2}));$('legendBolts').appendChild(el);legendBolts.push({el,x:dogX()+72,y:GROUND+S.y-68,life:.8,total:.8,kind:'rail'});S.legendPulse=.38;beep(720,.1,'sawtooth',.016)}
function legendDash(){if(S.mode!=='play')return;if(playSkill()==='rail'){if(S.phase==='running')railShot();else S.legendPulse=.35}if(playSkill()==='chrono'&&S.chrono>0)legendBurst(dogX()+15,GROUND+S.y-65,'#d9d0ff')}
function legendSuper(){if(S.mode!=='play')return;S.legendPulse=.7;const sk=playSkill();if(sk==='leviathan'){for(const o of items)if(o.x>dogX()-50&&o.x<dogX()+480){if(o.token)continue;if(o.coin||o.coffee)legendCollect(o);else legendBreak(o,'#affbe8')}toast('鲸落 / 480范围，鲸息4.4秒','#c9fff1');if(S.phase==='boss'&&B.state==='open'){shootBoss(2);S.legendSerial=B.openSerial}}else if(sk==='chrono'){S.chrono=2.4;S.cool=Math.min(S.cool,.2);toast('时间拒收 / 2.4秒归我','#ddd4ff');beep(310,.3,'triangle',.018)}else if(sk==='orbit'){toast('万纸归宗 / 手动双纸，开窗才反击','#c9efff');if(S.phase==='boss'&&B.state==='open')shootBoss(2)}else if(sk==='rail')toast('雷贯穿街 / 一雷最多穿三障','#b9faff')}
function tickLegend(dt){tickSkinTrails(dt);const stopped=Math.min(dt,S.chrono);S.chrono=Math.max(0,S.chrono-dt);S.legendPulse=Math.max(0,S.legendPulse-dt);if(S.mode==='play'&&playSkill()==='orbit'){S.orbitTick=Math.max(0,S.orbitTick-dt);if(S.phase==='running'&&S.orbitTick===0&&S.energy>=1){const o=items.find(o=>!o.done&&!o.token&&!o.ghost&&!o.coin&&!o.coffee&&Math.abs(o.x-(dogX()+17))<100&&Math.abs((o.y-37)-(GROUND+S.y-65))<90);if(o){const before=o.done;legendBreak(o,'#c3deff');if(o.done&&!before)S.energy=Math.max(0,S.energy-1);S.orbitTick=2.1;S.legendPulse=.17;beep(760,.05,'triangle',.009)}}}
 if(S.mode==='play'&&playSkill()==='leviathan'&&S.freedom>0&&S.phase==='running'){S.whaleTick=Math.max(0,S.whaleTick-dt);if(S.whaleTick===0){for(const o of items)if(!o.done&&!o.token&&!o.ghost&&o.x>dogX()-40&&o.x<dogX()+180){if(o.coin||o.coffee)legendCollect(o);else legendBreak(o,'#b4ffe5')}S.whaleTick=1}}
 const moving=legendBolts;legendBolts=[];for(const b of moving){b.life-=dt;if(b.kind==='rail'){b.x+=1050*dt;b.broken=b.broken||0;for(const o of items)if(!o.done&&!o.token&&!o.ghost&&Math.abs(o.x-b.x)<70&&(o.coin||o.coffee||Math.abs(o.y-37-b.y)<88)){if(o.coin||o.coffee)legendCollect(o);else if(b.broken<3){const before=o.done;legendBreak(o,'#9bf5ff');if(!before&&o.done)b.broken++}}attr(b.el,'transform',`translate(${b.x},${b.y})`)}else attr(b.el,'transform',`translate(${b.x},${b.y}) scale(${1+(1-b.life/b.total)*1.7})`);attr(b.el,'opacity',Math.max(0,b.life/b.total));if(b.life<=0)b.el.remove();else legendBolts.push(b)}return dt-stopped}
