show('legendOrbit',running&&S.mode==='play'&&playSkill()==='orbit');set('legendOrbit','transform',`translate(${x},${y}) rotate(${reduced?0:clock*85})`);show('legendWhale',running&&playSkill()==='leviathan'&&S.freedom>0);set('legendWhale','transform',`translate(${x+55},${GROUND+40+Math.sin(clock*3)*3}) scale(${mobile?.78:1})`);set('legendWhale','opacity',S.freedom>0?Math.min(1,S.freedom*2)*.8:0);show('chronoFX',running&&S.chrono>0);set('chronoFX','transform',`translate(${x},${y})`);set('chronoHands','transform',`rotate(${S.chrono>0?(2.4-S.chrono)*24:0})`);set('chronoFX','opacity',.68);set('legendFlash','opacity',reduced?0:Math.min(.11,S.legendPulse*.16));pos('legendHUD',mobile?390:900,S.phase==='boss'||S.phase==='bossVictory'?mobile?245:196:mobile?192:183);show('legendHUD',running&&S.mode==='play'&&isLegend());if(running&&isLegend()){text('legendStatus',playSkill()==='chrono'&&S.chrono>0?'时停 '+S.chrono.toFixed(1)+'s':playSkill()==='leviathan'&&S.freedom>0?'鲸息 '+S.freedom.toFixed(1)+'s':playSkill()==='orbit'?`纸护 / ${S.orbitTick>0?S.orbitTick.toFixed(1)+'s':'待拦截'}`:playSkill()==='rail'?'雷贯穿街 / 冲刺出雷':'拒绝时间 / 六杯开时停')}
