let shopPage=0,detailId='',buyConfirm='',demoClock=0;const shopCards=()=>CATALOG[shopTab].slice(shopPage*4,shopPage*4+4);const fmt=n=>Number(n).toLocaleString('en-US');
function changePage(n){shopPage=Math.max(0,Math.min(Math.ceil(CATALOG[shopTab].length/4)-1,shopPage+n));buyConfirm='';shopNotice='';shopLayout();renderShop()}
function openDetail(id){const c=CATALOG[shopTab].find(c=>c.id===id);if(!c)return;detailId=id;demoClock=0;show('shopDetail',true);detailLayout();text('detailTitle',c.name);text('detailPrice',(c.tier||'街头常备')+' / '+fmt(c.price)+' 金币');wrapText('detailBody',c.detail||c.desc,mobile?25:32);text('detailNote',shopTab==='skins'?'预览不改变你当前皮肤 / 纯外观':'预览不扣金币，不计成绩 / 买后替换单槽技能');text('detailPreviewLabel',shopTab==='skins'?'试穿预览 / 衣服配件与仪轨':'招式演示 / 点下方重播');const art=$('detailDog');art.replaceChildren();if(shopTab==='skins'){const dog=cleanClone($('dogBody'));dog.removeAttribute('transform');paintSkin(dog,c);art.appendChild(dog)}else{const dog=cleanClone($('dogBody'));dog.removeAttribute('transform');art.appendChild(dog)}$('detailFX').replaceChildren();drawPreviewFX(c);renderDemo();$('detailCloseBtn').focus()}
function wrapText(id,str,cols){const el=$(id);el.replaceChildren();const parts=Array.from(str);let y=0;while(parts.length){const span=node('tspan',{x:0,dy:y?29:0});span.textContent=parts.splice(0,cols).join('');el.appendChild(span);y++}}
