function purchase(id){if(!shopOpen||detailId)return;const tab=shopTab,c=CATALOG[tab].find(c=>c.id===id);if(!c)return;if(['running','boss','bossVictory','bossGate','bossResult'].includes(S.phase)){shopNotice='本局装备锁定 / 回封面再买换，金币不会丢';buyConfirm='';renderShop();return}const owned=tab==='skins'?wallet.ownedSkins:wallet.ownedSkills;if(!owned.includes(id)){if(wallet.balance<c.price){shopNotice='无米 / 还差 '+fmt(c.price-wallet.balance)+' 枚金币';buyConfirm='';renderShop();return}if(c.price>=800&&buyConfirm!==id){buyConfirm=id;shopNotice='再点一次确认 / '+c.name+' · '+fmt(c.price)+' 金币';renderShop();return}wallet.balance-=c.price;owned.push(id)}buyConfirm='';if(tab==='skins'){wallet.skin=id;applySkin();shopNotice='换好了 / '+c.name}else{wallet.skill=wallet.skill===id?'':id;shopNotice=wallet.skill?'已装配 / '+c.name:'已卸下 / 原装继续跑'}saveWallet();renderShop();render()}
