function renderBossBeam(){const high=B.pattern==='high'||B.pattern==='double'&&B.state==='active'&&B.elapsed>=.65,y=high?295:410,h=high?152:151,first=high&&B.pattern==='double'?.94:.22,stop=high?(B.pattern==='double'?1.14:.48):.38,active=B.state==='active',warning=B.state==='telegraph'||active&&B.elapsed<first,key=(warning?'warn':active?'fire':'off')+':'+(high?'high':'low')+':'+B.pattern;const left=120,width=mobile?600:1010,c=high?'#df92f2':'#ffb264';if($('bossWarnings').getAttribute('data-key')!==key){set('bossWarnings','data-key',key);$('bossWarnings').replaceChildren();$('bossWaves').replaceChildren();if(warning||active){const zone=node('rect',{x:left,y,width,height:h,rx:8,fill:c,'fill-opacity':.16,stroke:c,'stroke-width':3,'stroke-dasharray':'14 8'});$('bossWarnings').appendChild(zone);const dangerY=high?370:516;for(let x=155;x<(mobile?700:1110);x+=110){$('bossWarnings').appendChild(node('path',{d:high?`M${x-11} ${dangerY-14}l11 13 11-13M${x} ${dangerY-28}v25`:`M${x-11} ${dangerY+9}l11-13 11 13M${x} ${dangerY+25}v-25`,stroke:c,'stroke-width':3,fill:'none','stroke-linecap':'round'}))}const label=node('text',{x:mobile?502:775,y:high?321:466,fill:high?'#f5d9ff':'#ffe2b9','font-size':20,'font-weight':800,'text-anchor':'middle'});label.textContent=high?'空中危险 / 落地安全':'地面危险 / 起跳避开';$('bossWarnings').appendChild(label);if(B.pattern==='double'&&!high){const next=node('text',{x:mobile?502:775,y:357,fill:'#e9b9f6','font-size':18,'text-anchor':'middle'});next.textContent='第二拍：落地';$('bossWarnings').appendChild(next)}const cy=high?368:527;const g=$('bossWaves');g.appendChild(node('rect',{x:left,y,width,height:h,rx:8,fill:c,'fill-opacity':.24}));for(const[sw,opacity]of[[64,.1],[31,.27],[16,.9],[5,1]])g.appendChild(node('path',{d:`M${left} ${cy}H${left+width}`,stroke:sw===5?'#fff8e5':c,'stroke-width':sw,opacity,'stroke-linecap':'round'}));g.appendChild(node('path',{d:`M${left} ${y+3}H${left+width}M${left} ${y+h-3}H${left+width}`,stroke:c,'stroke-width':2,opacity:.9}));for(let x