// 5.0 additive routes, archive, local developer grant. The password is not a security boundary.
const ROUTES={story:{name:'四幕故事',duration:120},cruise:{name:'江风兜风',duration:90},contract:{name:'街头委托',duration:60},endless:{name:'凌晨循环',duration:900},dojo:{name:'拆机道场',duration:120}};
const ACHIEVEMENTS=[['first','今晚出门','完成任意亲玩路线'],['cruise','江风不催','完成一次江风兜风'],['contract','委托接住','街头委托达成至少一项目标'],['triple','全单拒收','一局街头委托达成三项目标'],['minute','熬过凌晨','凌晨循环生存60秒'],['three','野狗三更','凌晨循环生存180秒'],['dojo','练到拆机','道场击败终审官'],['story','把故事跑完','完成原版四幕亲玩故事'],['perfect','不碰审批','原版主线零受击'],['cat','七下摸狗','封面摸狗七下'],['whale','纸鲸回信','故事江边，亲手点一下纸鲸'],['secret','今晚自由','找到一处隐藏口令']];
const journeyDefaults=()=>({version:1,devClaimed:false,settings:{motion:'system'},records:{},achievements:[],secrets:[],runs:0});
let journey=journeyDefaults();
try{const old=JSON.parse(localStorage.getItem('nightOffProgressV4')||'null'),raw=old?.voyage;if(raw&&typeof raw==='object'){journey.devClaimed=raw.devClaimed===true;journey.settings.motion=['system','reduce','full'].includes(raw.settings?.motion)?raw.settings.motion:'system';journey.achievements=[...new Set((Array.isArray(raw.achievements)?raw.achievements:[]).filter(x=>ACHIEVEMENTS.some(a=>a[0]===x)))];journey.secrets=[...new Set((Array.isArray(raw.secrets)?raw.secrets:[]).filter(x=>['dog','whale','konami','0217','night'].includes(x)))];journey.runs=bounded(raw.runs,0,1000000);for(const id of ['story','cruise','contract','endless','dojo'])for(const gear of ['stock','equipped']){const k=id+':'+gear,r=raw.records?.[k];if(r&&typeof r==='object')journey.records[k]={runs:bounded(r.runs,0,1000000),best:bounded(r.best,0,10000000),time:bounded(r.time,0,900),wins:bounded(r.wins,0,1000000)}}}}catch(e){storageOK=false}
wallet.voyage=journey;
function bounded(x,a,b){return Math.max(a,Math.min(b,Math.floor(Number(x)||0)))}
const vDefaults={route:'story',life:3,finished:false,reason:'',milestone:0,shieldMark:0,elapsed:0,goals:[],daily:'',gear:'stock',resultCoins:0,recorded:false,tier:0};
const V={...vDefaults};let nextRoute='story',voyagePanel='',voyageWasPaused=false,voyageFocus=null,archivePage=0,pin='',pinMessage='',petCount=0,konamiIndex=0,settingNotice='',archiveClock=0;
function applyMotion(){reduced=journey.settings.motion==='reduce'||journey.settings.motion==='system'&&matchMedia('(prefers-reduced-motion: reduce)').matches;svg.classList.toggle('gentle',reduced)}
applyMotion();try{matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',applyMotion)}catch(e){}
function saveJourney(){wallet.voyage=journey;saveWallet()}
function dateKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function daySeed(str){let h=2166136261;for(const c of str){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function beginVoyage(mode){const route=mode==='play'&&ROUTES[nextRoute]?nextRoute:'story';nextRoute='story';Object.assign(V,vDefaults,{route,goals:[],gear:wallet.skill?'equipped':'stock'});if(route==='contract'){V.daily=dateKey();const d=daySeed(V.daily);seed=d;V.goals=[{kind:'coffee',name:'冰美式',need:6+d%3},{kind:'smashed',name:'撕碎通知',need:10+d%5},{kind:'nearMiss',name:'擦身闪避',need:2+d%2}]}else if(route==='endless')seed=daySeed('endless-v5');else if(route==='cruise')seed=71;S.safeGap=0}
function abandonVoyage(){V.finished=true;V.route='story';V.recorded=false;nextRoute='story'}
function playRoute(id){if(!ROUTES[id]||id==='story')id='story';closeVoyagePanel(false);nextRoute=id;start('play');if(id==='dojo'){S.t=120;S.bossEligible=true;S.completedMain=false;mainSnapshot={...S};startBoss();text('subtitleLine','练习不发金币 / 主线资格不受影响')}render()}
function retryVoyage(){if(voyagePanel)return;if(isMap()&&S.phase==='bossGate'){mapBossStart();return}if(isMap()&&S.phase==='ending'){playMap(M.id);return}if(['boss','bossVictory','bossResult'].includes(S.phase)){startBoss();return}if(V.route!=='story'){playRoute(V.route);return}start(S.mode)}
function runDuration(){return ROUTES[V.route]?.duration||120}
function voyageCoinValue(){return isMap()?1:isExtra()?1:V.route==='story'?1:3}
function voyageSpeed(base){if(isMap())return mapSpeed();if(isExtra())return extraSpeed(base);if(V.route==='cruise')return 215;if(V.route==='contract')return 300;if(V.route==='endless')return 300+Math.min(240,Math.floor(S.t/30)*18);return base}
function voyageGap(base){if(isMap())return night().gap+rnd()*.12;if(isExtra())return extraGap();if(V.route==='cruise')return 1.58+rnd()*.2;if(V.route==='contract')return .97+rnd()*.12;if(V.route==='endless')return Math.max(.76,1.14-Math.floor(S.t/30)*.027)+rnd()*.1;return base}
function canVoyageSpawn(){return V.route==='story'?S.t<113:V.route==='endless'?S.t<896:S.t<runDuration()-3}
function spawnVoyage(){if(isMap()){spawnMap();return}if(isExtra()){spawnExtra();return}const list=V.route==='cruise'?[['coffee',-54],['folder',0],['coffee',-145],['coin',-60],['notice',-162],['coffee',-54]]:[['coffee',-54],['folder',0],['notice',-162],['coffee',-145],['pair',0],['coffee',-54],['notice',0],['coffee',-220],['folder',0],['notice',-162],['coffee',-80]];const index=S.spawnIndex++,rotation=V.route==='contract'?daySeed(V.daily)%list.length:0;const [type,height]=list[(index+rotation)%list.length],next=list[(index+rotation+1)%list.length];const speed=voyageSpeed(300);S.safeGap=next[0]==='notice'&&next[1]<0?(type==='pair'?Math.max(1.5,530/speed):type==='folder'||type==='notice'?Math.max(1.1,430/speed):0):0;const base=mobile?930:1400;const made=items.length;if(type==='pair'){spawnOne('folder');spawnOne('notice',0,base+Math.max(165,speed*.45))}else spawnOne(type,height);if(V.route==='endless'&&S.t>=60&&index%3===1){for(const o of items.slice(made))if(!o.coin&&!o.coffee){o.armored=true;const seal=node('g');seal.appendChild(node('circle',{cy:-37,r:18,fill:'#512e3f',stroke:'#ffc4a1','stroke-width':2}));const t=node('text',{y:-31,'text-anchor':'middle','font-size':16,fill:'#ffe7c5','font-weight':800});t.textContent='章';seal.appendChild(t);o.el.appendChild(seal)}}if(index%2===0){for(let i=0;i<5;i++)spawnOne('coin',[-52,-97,-126,-97,-52][i],base+85+i*43)}}
function voyageDamage(){mapDamage();extraDamage();if(V.route==='endless')V.life=Math.max(0,V.life-1)}
function tickVoyage(dt){if(isMap()){tickMap();return}if(isExtra()){tickExtra(dt);return}if(V.route==='story'||V.finished||S.phase!=='running')return;V.elapsed=S.t;V.tier=Math.floor(S.t/30);if(V.route==='endless'){const m=Math.floor(S.t/30);while(V.milestone<m){V.milestone++;awardCoins(20,'夜路里程')}const shield=Math.floor(S.t/60);if(shield>V.shieldMark){V.shieldMark=shield;S.guard=Math.min(1,S.guard+1);toast('夜路补给 / 一枚纸盾','#c7e4ff')}if(V.life===0)finishVoyage('out')}if(!V.finished&&S.t>=runDuration())finishVoyage('complete')}
function completedGoals(){return V.goals.filter(g=>S[g.kind]>=g.need).length}
function unlockJourney(id){if(journey.achievements.includes(id))return;journey.achievements.push(id);saveJourney()}
function secretFound(id){if(journey.secrets.includes(id))return false;journey.secrets.push(id);if(id==='dog')unlockJourney('cat');else if(id==='whale')unlockJourney('whale');else if(id!=='night')unlockJourney('secret');saveJourney();return true}
function recordRoute(won=false){if(V.recorded||S.mode!=='play')return;V.recorded=true;journey.runs++;const key=V.route+':'+V.gear,old=journey.records[key]||{runs:0,best:0,time:0,wins:0};old.runs++;old.best=Math.max(old.best,voyageScore());old.time=Math.max(old.time,Math.min(900,V.route==='dojo'?B.t:S.t));old.wins+=won?1:0;journey.records[key]=old;unlockJourney('first');if(V.route==='story'){unlockJourney('story');if(S.hits===0)unlockJourney('perfect')}if(V.route==='cruise'&&S.t>=90)unlockJourney('cruise');if(V.route==='contract'){if(completedGoals()>0)unlockJourney('contract');if(completedGoals()===3)unlockJourney('triple')}if(V.route==='endless'){if(S.t>=60)unlockJourney('minute');if(S.t>=180)unlockJourney('three')}if(V.route==='dojo'&&won)unlockJourney('dojo');saveJourney()}
function recordStory(){if(V.route==='story')recordRoute(S.bossWon)}
function voyageScore(){return V.route==='endless'?Math.floor(S.t)*10+score():V.route==='dojo'?S.bossWon?1000+Math.max(0,300-Math.floor(B.t)):B.landed*30:score()}
function finishVoyage(reason='complete'){if(isMap()){if(S.phase==='running')mapGate();else mapSettle(false);return}if(isExtra()){finishExtra(reason);return}if(V.finished||V.route==='story')return;if(V.route==='dojo'&&reason!=='victory'&&S.phase==='bossResult')reason='practice';if(V.route==='cruise'&&reason==='complete')awardCoins(40,'江风收工');if(V.route==='contract'&&reason==='complete')awardCoins(60+25*completedGoals(),'委托结算');V.resultCoins=S.runCoins;V.reason=reason;V.elapsed=V.route==='dojo'?B.t:S.t;recordRoute(reason==='victory');V.finished=true;clearWorld();for(const o of shots)o.el.remove();shots=[];$('bossShots').replaceChildren();S.phase='ending';S.paused=false;S.dash=0;S.freedom=0;S.chrono=0;S.y=0;S.offset=0;svg.classList.remove('paused');for(const id of['hud','skillHud','subtitle','revealCaption','freedomBanner','perfectBadge','bossHud','bossCallout','bossGate','bossResult','bossWorld'])show(id,false);show('ending',true);S.ending=V.route==='cruise'?'江风不催人':V.route==='contract'?completedGoals()===3?'三单齐收，今晚自由':'委托收工，不用加班':V.route==='endless'?reason==='out'?'耐心用完，夜路还在':'凌晨循环，自愿收工':reason==='victory'?'练熟了，拆机就行':'道场收工，主线不动';text('endTitle',S.ending);text('endLine',V.route==='cruise'?'慢慢跑。没有谁在后面打卡。':V.route==='contract'?V.goals.map(g=>`${g.name} ${Math.min(S[g.kind],g.need)} / ${g.need}`).join(' · '):V.route==='endless'?`生存 ${Math.floor(V.elapsed)} 秒 / 强度 ${V.tier+1} / 原装与装备分榜`:'三阶段练习 / 不发金币，不刷主线徽章');text('endStats',`咖啡 ${S.coffee} / 撞飞 ${S.smashed} / 擦身 ${S.nearMiss} / 连击 ${S.maxCombo}`);text('bestText',`夜航分 ${voyageScore()} · ${V.gear==='stock'?'原装榜':'装备榜'} · 本局 +${S.runCoins} 币`);text('badgeText',`夜航成就 ${journey.achievements.length} / ${ACHIEVEMENTS.length} · 档案里可查看`);text('ticketHint','夜航票根仅在本机生成');beep(760,.2);render()}
function voyageSnapshot(){return {...V,goals:V.goals.map(g=>({...g,current:S[g.kind]})),panel:voyagePanel,devClaimed:journey.devClaimed,motion:journey.settings.motion,reduced,achievements:[...journey.achievements],secrets:[...journey.secrets],records:JSON.parse(JSON.stringify(journey.records)),runs:journey.runs,pinLength:pin.length}}
function openVoyagePanel(which){if(hubOpen)toggleHub(false);if(shopOpen)toggleShop(false);if(!voyagePanel){voyageWasPaused=S.paused;voyageFocus=document.activeElement;if(['running','boss','bossVictory'].includes(S.phase))pause(true)}voyagePanel=which;for(const id of ['voyageMenu','voyageArchive','voyageDev','voyageSettings'])show(id,id==={menu:'voyageMenu',archive:'voyageArchive',dev:'voyageDev',settings:'voyageSettings'}[which]);show('voyageOverlay',true);pin='';pinMessage='';settingNotice='';if(which==='archive'){archivePage=0;if(new Date().getHours()<5&&secretFound('night'))settingNotice='02:17 / 我不是没想过。只是白天懒得说。'}voyageLayout();renderVoyagePanel();panelButtons()[0]?.focus()}
function closeVoyagePanel(resume=true){if(!voyagePanel)return;voyagePanel='';show('voyageOverlay',false);pin='';if(resume&&!voyageWasPaused&&['running','boss','bossVictory'].includes(S.phase))pause(false);last=performance.now();if(resume&&voyageFocus?.isConnected)voyageFocus.focus()}
function panelButtons(){const root=$({menu:'voyageMenu',archive:'voyageArchive',dev:'voyageDev',settings:'voyageSettings'}[voyagePanel]||'voyageMenu');return Array.from(root.querySelectorAll('.button')).filter(e=>!e.closest('.hide'))}
function devKey(k){if(voyagePanel!=='dev')return;if(k==='back')pin=pin.slice(0,-1);else if(k==='clear')pin='';else if(/^\d$/.test(k)&&pin.length<6)pin+=k;pinMessage='';renderVoyagePanel()}
function redeemDev(){if(voyagePanel!=='dev')return;if(pin==='0217'){secretFound('0217');pinMessage='凌晨 02:17 / 无米也能兜风。';pin='';renderVoyagePanel();return}if(pin!=='546603'){pinMessage='口令不对 / 没有改动金币';pin='';renderVoyagePanel();return}if(journey.devClaimed){pinMessage='本浏览器已领取 / 不重复发米';pin='';renderVoyagePanel();return}try{const live=JSON.parse(localStorage.getItem('nightOffProgressV4')||'null');if(live?.voyage?.devClaimed===true){journey.devClaimed=true;wallet.balance=bounded(live.balance,0,1000000000);pinMessage='同存档已在另一页领取 / 不重复发米';pin='';renderVoyagePanel();render();return}}catch(e){storageOK=false}const before=wallet.balance;journey.devClaimed=true;wallet.balance=Math.min(1000000000,wallet.balance+100000);saveJourney();pinMessage=`解锁成功 / 金币 +${fmt(wallet.balance-before)}${storageOK?' · 已保存':' · 存储受限，仅本页有效'}`;pin='';render();renderVoyagePanel()}
function cycleMotion(){const choices=['system','reduce','full'];journey.settings.motion=choices[(choices.indexOf(journey.settings.motion)+1)%3];applyMotion();saveJourney();settingNotice=storageOK?'偏好已保存在当前浏览器':'存储受限 / 本次仍有效';renderVoyagePanel();render()}
function tickVoyageIdle(dt){archiveClock+=dt}
function renderVoyage(){show('voyageBtn',S.phase==='cover'&&!shopOpen&&!voyagePanel);show('archiveBtn',S.phase==='cover'&&!shopOpen&&!voyagePanel);show('quickMenuBtn',S.phase!=='cover'&&!shopOpen&&!voyagePanel);const active=V.route!=='story'&&['running','boss','bossVictory'].includes(S.phase);show('voyageHUD',active&&!shopOpen&&!voyagePanel);show('cashOutBtn',V.route==='endless'&&S.phase==='running'&&!shopOpen&&!voyagePanel);text('voyageRouteLabel','夜航 / '+(ROUTES[V.route]?.name||''));if(active){text('voyageState',V.route==='cruise'?'江风慢跑 / 碰撞不扣耐心':V.route==='contract'?V.goals.map(g=>`${g.name.slice(0,2)} ${Math.min(g.need,S[g.kind])}/${g.need}`).join(' · '):V.route==='endless'?`耐心 ${'◆'.repeat(V.life)}${'◇'.repeat(3-V.life)} / 强度 ${V.tier+1} / ${S.t>=60?'镀章不能被动撕碎':'每60秒补纸盾'}`:'道场练习 / 不发金币，不影响主线');text('timerText',V.route==='dojo'?`练习 / ${Math.floor(B.t)} 秒`:`${ROUTES[V.route].name} / ${Math.floor(S.t)} : ${runDuration()}`);if(V.route!=='dojo'){set('progressFill','width',(mobile?640:1200)*S.t/runDuration());text('chapterText',ROUTES[V.route].name);text('hitText',V.route==='cruise'?'江风无伤':'被催 '+S.hits+' 次');show('perfectBadge',false);text('subtitleLine',V.route==='cruise'?['不用跳也能走完。想跳就跳。','没消息催你。这段江风只管吹。','顺手捞点金币，买件好看的。','有钱兜风。没钱也兜风。'][S.chapter]:V.route==='contract'?`今日委托 ${V.daily} / 全部装备可用，按装配分榜`:'越跑越狠，速度和密度都有上限 / 不想跑就收工');text('hintText',V.route==='endless'?'三格耐心 / 金章挡被动技能，可跳或冲刺通过 / 随时收工':'左跳 · 右冲 · 六杯开大招 / 菜单打开自动暂停')}else{text('subtitleLine','拆机练习 / 绿盾开窗再反击，练习不赚币')}}if(S.phase==='cover')text('hintText','放映看故事 / 逃班玩主线 / 夜航有四种新玩法');if(S.phase==='ending'&&V.route!=='story')text('ticketHint',`本局金币 +${S.runCoins} · 钱包 ${fmt(wallet.balance)} / 夜航票根不上传`);if(voyagePanel)renderVoyagePanel()}
function renderVoyagePanel(){if(!voyagePanel)return;text('voyageBalance','金币 '+fmt(wallet.balance));text('voyageStorage',storageOK?'离线单文件 / 同一浏览器同一主入口保存':'存储受限 / 当前能玩，关页可能不保留');if(voyagePanel==='menu'){text('menuContract','60秒 / 今日固定路线与目标 / 基础60 + 每单25币');text('menuEndless','3格耐心 / 强度逐步增加 / 每30秒20币');text('menuEquip','本局 '+(wallet.skill?CATALOG.skills.find(c=>c.id===wallet.skill)?.name:'原装无技能')+' / 回封面商店换装')}if(voyagePanel==='dev'){text('devPin',pin?'● '.repeat(pin.length):'输入六位口令');text('devStatus',pinMessage|| (journey.devClaimed?'已领取 100,000 金币 / 同存档仅一次':'密码解锁 +100,000 金币 / 不影响本局成绩'));text('devNote','离线彩蛋口令，不是安全锁 / 清存档会重置标记');text('devClaimText',journey.devClaimed?'核验口令':'解锁领米')}if(voyagePanel==='settings'){text('motionChoice','动画 / '+({system:'跟随系统',reduce:'减少动画',full:'完整动画'}[journey.settings.motion]));text('settingMessage',settingNotice||'减少动画不削弱技能 / 当前 '+(reduced?'减少':'完整'));text('settingSound',sound?'音效：开（主界面可切换）':'音效默认关（主界面可切换）')}if(voyagePanel==='archive'){text('archiveHead',archivePage===0?'夜航记录 / 原装与装备分榜':'夜航成就 / '+journey.achievements.length+' / '+ACHIEVEMENTS.length);const lines=[];if(archivePage===0){for(const[id,c]of Object.entries(ROUTES).filter(([id])=>['story','cruise','contract','endless','dojo'].includes(id))){lines.push(c.name);for(const gear of ['stock','equipped']){const r=journey.records[id+':'+gear];lines.push(`  ${gear==='stock'?'原装':'装备'} · ${r?`${r.runs}局 / 最佳${r.best} / 最长${Math.floor(r.time)}秒`:'还没跑过'}`)}}}else for(const[id,name,desc]of ACHIEVEMENTS)lines.push((journey.achievements.includes(id)?'◆ ':'◇ ')+name+' / '+desc);renderLines('archiveBody',lines,mobile?20:22,mobile?46:compact?28:34);text('archiveNote',settingNotice||`完成 ${journey.runs} 局 / 彩蛋 ${journey.secrets.length} / 开发者领米不计成绩`);text('archivePageText',archivePage===0?'1 / 2':'2 / 2')}}
function renderLines(id,lines,size,gap){const g=$(id);const signature=lines.join('\n')+'|'+size+'|'+gap;if(g.getAttribute('data-copy')===signature)return;g.setAttribute('data-copy',signature);g.replaceChildren();lines.forEach((line,i)=>{const t=node('text',{x:0,y:i*gap,fill:line.startsWith('◆')?'#e9cf91':line.startsWith('◇')?'#7795a6':'#c7dfdb','font-size':size,'font-weight':line.startsWith('  ')?400:700});t.textContent=line;g.appendChild(t)})}
