],'font-size',mobile?17:17)});set('menuEquip','x',30);set('menuEquip','y',mobile?955:compact?627:658);set('menuEquip','font-size',mobile?19:21);pos('devOpenBtn',30,h-105);buttonSize('devOpenBtn',mobile?155:178,65);pos('settingsOpenBtn',mobile?208:226,h-105);buttonSize('settingsOpenBtn',mobile?155:178,65);pos('archiveMenuBtn',mobile?380:422,h-105);buttonSize('archiveMenuBtn',mobile?92:178,65);attr($('archiveMenuBtn').querySelector('text'),'font-size',mobile?17:22);pos('archiveBody',30,mobile?217:compact?170:192);set('archiveHead','y',mobile?174:138);set('archiveNote','x',30);set('archiveNote','y',h-150);set('archiveNote','font-size',mobile?17:20);pos('archiveFlipBtn',30,h-105);buttonSize('archiveFlipBtn',mobile?190:220,65);set('archivePageText','x',mobile?250:286);set('archivePageText','y',h-62);set('devIntro','y',mobile?186:145);set('devIntro','font-size',mobile?18:21);set('devPin','x',w/2);set('devPin','y',mobile?286:217);set('devStatus','x',w/2);set('devStatus','y',mobile?351:269);set('devStatus','font-size',mobile?18:21);const kw=mobile?170:170,kh=mobile?91:compact?48:59,ky=mobile?399:compact?254:292,kx=(w-(kw*3+40))/2;for(let i=0;i<12;i++){pos('devKey'+i,kx+(i%3)*(kw+20),ky+Math.floor(i/3)*(kh+17));buttonSize('devKey'+i,kw,kh)}pos('devClaimBtn',kx,ky+4*(kh+17)+12);buttonSize('devClaimBtn',kw*3+40,mobile?81:63);set('devNote','x',w/2);set('devNote','y',h-153);set('devNote','font-size',mobile?15:17);pos('motionBtn',30,mobile?263:213);buttonSize('motionBtn',w-60,mobile?100:80);set('motionChoice','x',(w-60)/2);set('settingMessage','y',mobile?417:340);set('settingSound','y',mobile?485:410);set('settingKeys','y',mobile?583:482);set('settingKeys','font-size',mobile?17:21);pos('settingsStoryBtn',30,mobile?688:550);buttonSize('settingsStoryBtn',mobile?355:480,80);if(voyagePanel)renderVoyagePanel()}
function voyageTicket(){if(isExtra())return extraTicket();const c=CATALOG.skins.find(c=>c.id===wallet.skin),sk=CATALOG.skills.find(c=>c.id===wallet.skill);return `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="600" viewBox="0 0 1000 600"><rect width="1000" height="600" rx="30" fill="#102435"/><path d="M32 103H968M32 488H968" stroke="#8dd7c0" stroke-dasharray="7 9"/><g font-family="system-ui,sans-serif"><text x="56" y="66" fill="#a2e8d0" font-size="26">NIGHT VOYAGE / 野狗逃班 5.0</text><text x="56" y="168" fill="#f9d896" font-size="46">${escapeXML(S.ending)}</text><text x="56" y="235" fill="#c0ddd6" font-size="26">${escapeXML(ROUTES[V.route].name)} / ${Math.floor(V.elapsed)} 秒 / ${V.gear==='stock'?'原装':'装备'}榜</text><text x="56" y="305" fill="#bcd5ce" font-size="26">咖啡 ${S.coffee} / 撞飞 ${S.smashed} / 擦身 ${S.nearMiss} / 夜航分 ${voyageScore()}</text><text x="56" y="365" fill="#f6d899" font-size="28">本局金币 +${S.runCoins} / ${V.route==='dojo'?'练习不发金币':'不上传数据'}</text><text x="56" y="428" fill="#aacfc5" font-size="24">${escapeXML(c.name)} / ${escapeXML(sk?.name||'原装无技能')}</text><text x="56" y="549" fill="#8caeaa" font-size="22">ONE WAY / 自愿出门，自愿收工 · ${escapeXML(dateKey())}</text></g></svg>`}
