$('voyageOverlay').addEventListener('pointerdown',e=>e.stopPropagation());$('voyageOverlay').addEventListener('click',e=>e.stopPropagation());
window.addEventListener('keydown',e=>{if(voyagePanel){const k=e.key;if(k==='Tab'){e.preventDefault();const b=panelButtons(),i=b.indexOf(document.activeElement);b[(i+(e.shiftKey?-1:1)+b.length)%b.length]?.focus();return}if(voyagePanel==='dev'&&(/^[0-9]$/.test(k)||k==='Backspace'||k==='Delete')){e.preventDefault();if(!e.repeat)devKey(k==='Backspace'?'back':k==='Delete'?'clear':k);return}if(k==='Enter'&&voyagePanel==='dev'&&!e.target.closest?.('.button')){e.preventDefault();redeemDev();return}if(k==='Escape'){e.preventDefault();['dev','settings'].includes(voyagePanel)?openVoyagePanel('menu'):closeVoyagePanel();return}return}if(hubOpen||S.phase!=='cover'||shopOpen)return;const keys=['ArrowUp','ArrowUp','ArrowDown','ArrowDown','ArrowLeft','ArrowRight','ArrowLeft','ArrowRight','b','a'];if(e.key===keys[konamiIndex]){e.preventDefault();konamiIndex++;if(konamiIndex===keys.length){konamiIndex=0;secretFound('konami');text('coverLine2','隐藏口令接住了 / 我不是没想过，只是不当众谈理想。')}}else konamiIndex=e.key===keys[0]?1:0},true);
