$('whaleReveal').setAttribute('pointer-events','all');$('whaleReveal').addEventListener('pointerdown',e=>{if(V.route==='story'&&S.mode==='play'&&S.phase==='running'&&S.t>94&&S.t<113&&!S.paused&&!voyagePanel&&!shopOpen){e.preventDefault();e.stopPropagation();secretFound('whale');toast('纸鲸回信 / 风知道哪边是海。','#c9f9ee')}});

// 5.1 merges the tested playground onto the frozen 5.0 night voyage.
// One wallet, one developer entry, independent daily/courier/raw endless/tutorial.
const EXTRA_ROUTES={courier:{name:'咖啡快送',duration:90,tag:'五站夜送 · 三杯护包',desc:['实际捡咖啡入包，最多三杯。','每18秒到站交货；受击丢一杯。','每杯4币，满包另+3；收工+15。'],color:'#ffd39c'},daily:{name:'每日同路',duration:75,tag:'同日期 · 同路线 · 统一原装',desc:['日历种子，横竖屏出怪位置相同。','所有装备技能禁用；皮肤照穿。','独立本地纪录，不冒充联网排行。'],color:'#c9c5ff'},wildrun:{name:'无尽夜跑',duration:Infinity,tag:'三格耐心 · 不补盾的野路',desc:['与凌晨循环独立：无自动盾和金章。','提速最高42%，密度最低0.86秒。','每30秒8币；可随时主动收工。'],color:'#a7f2cf'},tutorial:{name:'上手练习',duration:30,tag:'30秒 · 真按钮 · 不计钱包',desc:['空格跳，Shift冲，中间大招。','统一原装，练习咖啡免费备好。','不赚金币，不记主线或夜航成绩。'],color:'#d6d49f'}};
Object.assign(ROUTES,EXTRA_ROUTES);
let hubOpen=false,hubTab='routes',hubWasPaused=false,hubFocus=null,hubMessage='',routeConfirm='',mapIndex=0;
const fieldDefaults=()=>({records:{},secrets:[],seen:[],contracts:[],storyRuns:0,bossWins:0,delivered:0,endlessBest:0,nightTint:0});
let field=fieldDefaults();
try{const raw=JSON.parse(localStorage.getItem('nightOffProgressV4')||'null')?.voyage?.extras;if(raw&&typeof raw==='object'){for(const k of ['storyRuns','bossWins','delivered','endlessBest'])field[k]=Math.max(0,Math.min(1e9,Number(raw[k])||0));for(const k of ['secrets','seen','contracts']){const allowed=k==='secrets'?['moon','cat','coffee','letter','whale']:k==='contracts'?['first','courier','wildrun','boss','secrets']:Array.from({length:12},(_,i)=>String(i));field[k]=Array.isArray(raw[k])?[...new Set(raw[k].filter(x=>allowed.includes(x)))]:[]}field.nightTint=[0,1,2].includes(raw.nightTint)?raw.nightTint:0;for(const[id,r]of Object.entries(raw.records||{}))if(/^(courier|wildrun|daily):/.test(id)&&r&&Number.isFinite(r.score))field.records[id]={score:Math.max(0,Math.floor(r.score)),t:Math.max(0,Math.min(1e8,Number(r.t)||0)),date:typeof r.date==='string'?r.date:''}}}catch(e){storageOK=false}
journey.extras=field;
const xDefaults=()=>({bag:0,delivered:0,station:1,date:'',seed:71,actions:[],fuel:false,milestone:0,settled:false,storyRemembered:false,bossRemembered:false});
let X=xDefaults();
const isExtra=()=>Object.hasOwn(EXTRA_ROUTES,V.route),routeSkill=route=>['daily','tutorial'].includes(route)?'':wallet.skill,playSkill=()=>isMap()?M.skill:routeSkill(V.route);
const CONTRACTS=[{id:'first',name:'自由不是请假',desc:'亲手完成一次原四幕主关',reward:60,ok:()=>field.storyRuns>=1},{id:'courier',name:'一杯都给你',desc:'咖啡快送累计交货12杯',reward:120,ok:()=>field.delivered>=12},{id:'wildrun',name:'别追，我还没累',desc:'无尽夜跑存活90秒',reward:160,ok:()=>field.endlessBest>=90},{id:'boss',name:'拆掉审批，不拆自己',desc:'正式隐藏终审官击破一次',reward:180,ok:()=>field.bossWins>=1},{id:'secrets',name:'街上没有白走的路',desc:'找到至少三枚街头暗号',reward:88,ok:()=>field.secrets.length>=3}];
function saveField(){journey.extras=field;saveJourney()}
function beginExtension(mode){X=xDefaults();X.date=dateKey();X.seed=V.route==='daily'?daySeed(X.date):V.route==='tutorial'?71:seed;if(isExtra()){seed=X.seed;V.gear=playSkill()?'equipped':'stock';if(V.route==='daily'){V.daily=X.date;S.guard=0}if(V.route==='tutorial')S.guard=0}}
function extraCoffee(){if(V.route==='courier'&&!V.finished)X.bag=Math.min(3,X.bag+1)}
function extraDamage(){if(V.route==='wildrun')V.life=Math.max(0,V.life-1);if(V.route==='courier'){X.bag=Math.max(0,X.bag-1);toast('杯架颠了一下 / 丢一杯','#ffc2c7')}}
function extraSpeed(base){return base*(V.route==='wildrun'?1+Math.min(.42,S.t/420):V.route==='courier'?1.05:V.route==='daily'?1.12:1)}
function extraGap(){return (V.route==='courier'||V.route==='tutorial'?1.16:V.route==='daily'?1.05:Math.max(.86,1.25-S.t/600))+rnd()*.14}
function spawnExtra(){const base=V.route==='daily'?930:mobile?930:1400,index=S.spawnIndex++,patterns=['courier','tutorial'].includes(V.route)?[['coffee',-54],['coffee',-140],['folder',0],['coffee',-54],['notice',-162],['coffee',-75],['pair',0],['coffee',-54]]:[['coffee',-54],['folder',0],['coffee',-145],['notice',-162],['folder',0],['pair',0],['coffee',-80],['notice',-162],['coffee',-145],['folder',0]],offset=V.route==='daily'?X.seed%patterns.length:0;const[type,y]=patterns[(index+offset)%patterns.length],next=patterns[(index+offset+1)%patterns.length];S.safeGap=next[0]==='notice'&&next[1]<0?(type==='pair'?2:type==='folder'?1.65:0):0;if(type==='pair'){spawnOne('folder',0,base);spawnOne('notice',0,base+185)}else spawnOne(type,y,base);if(index%2===0){for(let i=0;i<5;i++)spawnOne('coin',[-52,-98,-128,-98,-52][i],base+95+i*46)}if(V.route==='wildrun'&&index>0&&index%13===0){spawnOne('coffee',-54,base+390);toast('路边热心狗 / 冰美式补给','#b6f3d4')}}
function extraAction(kind){if(V.route==='tutorial'&&!S.paused&&!X.actions.includes(kind)){X.actions.push(kind);toast(kind==='jump'?'跳了 / 再按一次二段跳':kind==='dash'?'冲了 / 短暂无敌，能撞开通知':'大招开了 / 六杯让世界静音','#e5edb4')}}
function tickExtra(dt){if(V.finished||S.phase!=='running')return;V.elapsed=S.t;if(V.route==='tutorial'){if(S.t>17&&S.energy<6&&X.actions.length>=2&&!X.fuel){X.fuel=true;S.energy=6;toast('练习咖啡备好了 / 点中间大招','#e8d8a0')}}else if(V.route==='wildrun'){const m=Math.floor(S.t/30);while(X.milestone<m){X.milestone++;awardCoins(8,'野路里程')}if(V.life===0){finishExtra('out');return}}else if(V.route==='courier'&&S.t>=X.station*18){const n=X.bag;X.bag=0;X.delivered+=n;const tip=n*4+(n===3?3:0);if(tip)awardCoins(tip,'交货');toast(n?`第${X.station}站 / 送达${n}杯 · +${tip}`:`第${X.station}站 / 无米`,'#ffe0ad');X.station++}if(S.t>=runDuration())finishExtra('complete')}
function extraScore(){return score()+(V.route==='wildrun'?Math.floor(S.t)*3:V.route==='courier'?X.delivered*35:0)}
function extraRecordKey(){return V.route+':'+(V.route==='daily'?X.date:V.gear)}
function finishExtra(reason){if(V.finished||X.settled)return;X.settled=true;if(V.route==='wildrun'){awardCoins(Math.min(60,Math.floor(S.t/6)),'野路收工');field.endlessBest=Math.max(field.endlessBest,S.t)}else if(V.route==='courier'){awardCoins(15,'快送收工');field.delivered+=X.delivered}else if(V.route==='daily')awardCoins(18,'每日收工');const points=extraScore();if(V.route!=='tutorial'){const key=extraRecordKey(),old=field.records[key];if(!old||points>old.score)field.records[key]={score:points,t:S.t,date:X.date};if(V.route==='daily'){for(const k of Object.keys(field.records))if(k.startsWith('daily:')&&k!==key)delete field.records[k]}for(const i of [S.chapter,4+S.chapter,V.route==='courier'?9:V.route==='daily'?10:8])if(!field.seen.includes(String(i)))field.seen.push(String(i));saveField()}V.finished=true;V.reason=reason;V.resultCoins=S.runCoins;clearWorld();for(const o of shots)o.el.remove();shots=[];$('bossShots').replaceChildren();S.phase='ending';S.paused=false;S.dash=0;S.freedom=0;S.chrono=0;S.y=0;S.vy=0;S.offset=0;S.score=points;svg.classList.remove('paused');for(const id of ['hud','skillHud','subtitle','revealCaption','freedomBanner','perfectBadge','bossHud','bossCallout','bossGate','bossResult','bossWorld'])show(id,false);show('ending',true);S.ending=V.route==='wildrun'?'风还在，我先歇了':V.route==='courier'?X.delivered>=9?'冰美式，准时送达':'无米，但没洒光':V.route==='daily'?'同一条街，不同的我':'会了，出门兜风';text('endTitle',S.ending);text('endLine',V.route==='wildrun'?reason==='out'?'三格耐心用完了，夜路还在。':'自己选的路，自己喊收工。':V.route==='courier'?`五站夜送 / 送达 ${X.delivered} 杯 / 咖啡不考勤`:V.route==='daily'?X.date+' / 全技能禁用，皮肤照穿。':'练习不计钱包，不改主线和夜航档案。');text('endStats',V.route==='courier'?`送达 ${X.delivered} 杯 / 被催 ${S.hits} 次 / 连击 ${S.maxCombo}`:`存活 ${Math.floor(S.t)} 秒 / 咖啡 ${S.coffee} / 被催 ${S.hits} 次`);text('bestText',V.route==='tutorial'?'上手练习 / 正式成绩未动':`${ROUTES[V.route].name} · ${points} 分 · 最佳 ${field.records[extraRecordKey()]?.score||0}`);text('badgeText',V.route==='daily'?'公平规则 / 同日期同路线 · 无联网排行':'自由手账 / 与原夜航档案分开记录');text('ticketHint','本机生成票根，不上传数据。');render()}
function extraSnapshot(){return{route:V.route,bag:X.bag,delivered:X.delivered,station:X.station,date:X.date,seed:X.seed,hubOpen,hubTab,routeConfirm,mapIndex,secrets:[...field.secrets],records:JSON.parse(JSON.stringify(field.records)),contracts:[...field.contracts]}}
function toggleHub(force){const next=typeof force==='boolean'?force:!hubOpen;if(next===hubOpen)return;if(next){if(shopOpen)toggleShop(false);if(voyagePanel)closeVoyagePanel();hubWasPaused=S.paused;hubFocus=document.activeElement;if(['running','boss','bossVictory'].includes(S.phase))pause(true);hubOpen=true;hubTab='routes';routeConfirm='';hubMessage='';hubLayout();renderHub();show('arcadePanel',true);$('hubCloseBtn').focus()}else{hubOpen=false;show('arcadePanel',false);if(!hubWasPaused&&['running','boss','bossVictory'].includes(S.phase))pause(false);last=performance.now();if(hubFocus?.isConnected)hubFocus.focus();else $('arcadeBtn').focus()}render()}
function setHubTab(tab){hubTab=tab;routeConfirm='';hubMessage='';hubLayout();renderHub()}
function nativeMenu(which='menu'){toggleHub(false);openVoyagePanel(which)}
function hubLayout(){const W=mobile?720:1280,H=mobile?1350:compact?800:940;set('hubVeil','width',W);set('hubVeil','height',H);set('hubFrame','width',W-44);set('hubFrame','height',H-42);set('hubTitle','font-size',mobile?42:44);pos('hubHead',mobile?44:62,72);for(const[id,i]of ['routeTab','mapTab','journalTab','settingsTab'].map((id,i)=>[id,i])){pos(id,mobile?44+i*161:62+i*289,mobile?153:142);buttonSize(id,mobile?147:269,68);attr($(id).querySelector('text'),'font-size',mobile?23:24)}pos('hubBody',mobile?44:62,mobile?251:235);set('hubBodyBG','width',mobile?632:1156);set('hubBodyBG','height',mobile?838:compact?384:523);pos('hubCloseBtn',W-(mobile?217:264),H-119);buttonSize('hubCloseBtn',mobile?172:202,72);pos('hubNativeBtn',mobile?44:62,H-119);buttonSize('hubNativeBtn',mobile?286:340,72);set('hubMessage','x',mobile?44:62);set('hubMessage','y',H-150);set('hubMessage','font-size',mobile?18:20);set('hubFoot','x',mobile?44:62);set('hubFoot','y',H-26);set('hubFoot','font-size',mobile?16:17);renderHubBody()}
function renderHub(){if(!hubOpen)return;for(const[t,id]of [['routes','routeTab'],['map','mapTab'],['journal','journalTab'],['settings','settingsTab']])$(id).classList.toggle('ready',hubTab===t);text('hubSubtitle','5.2 十二夜路 / 十二关 · 十二守夜者 · 旧玩法全留');text('hubMessage',hubMessage||(['running','boss','bossVictory','bossGate','bossResult'].includes(S.phase)?'本局已暂停 / 更换玩法需再点确认':'原四幕与四条夜航支线全保留 / 领米在原开发者'));text('hubFoot',storageOK?'离线 · 同一个钱包 · 只装一个技能':'存储受限 / 本次能玩，关页可能不保留');renderHubBody()}
function svgButton(parent,id,label,x,y,w,h,fn,color='#79a49a'){const b=node('g',{id,class:'button',role:'button',tabindex:0,'aria-label':label,transform:`translate(${x},${y})`});b.appendChild(node('rect',{width:w,height:h,rx:13,fill:'#142c35',stroke:color}));const t=node('text',{x:w/2,y:h/2+8,'text-anchor':'middle',fill:'#e4eee1','font-size':mobile?23:21,'font-weight':700});t.textContent=label;b.appendChild(t);parent.appendChild(b);bind(id,fn);return b}
