function renderHubBody(){if(!hubOpen)return;const g=$('hubDynamic');g.replaceChildren();if(hubTab==='routes')drawRoutes(g);else if(hubTab==='map')drawMap(g);else if(hubTab==='journal')drawJournal(g);else drawSettings(g)}
