const MAP_PLACES=[['雨夜门口','门禁不问理想，只问你什么时候回来。','雨巷 / 静静走出去'],['凌晨骑楼','霓虹灯不比太阳高贵，但今天是它陪你。','骑楼 / 雨落得慢一点'],['冰美式窗口','店员问要不要加糖。我说消息已经够甜了。','小店 / 咖啡续命'],['旧书铺','把未读通知夹进书里，它就安静了。','旧书 / 不回复也能翻页'],['机修棚','自由不是永远不坏，是坏了还想修。','机修 / 不给灵魂打卡'],['地铁末班','错过末班也没关系，街还在。','站台 / 到站不等于终点'],['高架底下','桥把车送远，风把话吹散。','高架 / 留点声给自己'],['屋顶电台','02:17。没有听众，我也在播。','屋顶 / 频率暂时自由'],['邕江南岸','不追那条鲸。它比我懂海。','江边 / 留白不需要审批'],['码头仓库','搬走的箱子都装着明天，今晚先不拆。','码头 / 今夜不验货'],['纸鲸灯会','没寄出的信，换了一种方式抵达。','灯会 / 不写收件人'],['天亮早市','天亮不是催我起床，是允许我收工。','早市 / 今天到这里']];
function drawMap(g){drawPlayableMap(g)}
function downloadLocal(body,name){try{const blob=new Blob([body],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElementNS('http://www.w3.org/1999/xhtml','a');a.href=url;a.download=name;document.documentElement.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),20000);return true}catch(e){hubMessage='预览器不支持下载 / 请用浏览器打开 HTML';text('hubMessage',hubMessage);return false}}
function savePostcard(){const p=MAP_PLACES[mapIndex],symbol=$('postcard'+mapIndex),body=`<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="760" viewBox="0 0 1000 760"><rect width="1000" height="760" fill="#081421"/><svg x="0" y="0" width="1000" height="600" viewBox="0 0 800 480">${symbol.innerHTML}</svg><g font-family="system-ui,sans-serif"><text x="40" y="650" fill="#ffe3b1" font-size="30">${escapeXML(p[0])} / 野狗逃班</text><text x="40" y="700" fill="#b5d7cf" font-size="21">${escapeXML(p[1])}</text></g></svg>`;if(downloadLocal(body,'野狗逃班-明信片-'+p[0]+'.svg')){hubMessage='明信片已生成 / 浏览器下载记录里见';text('hubMessage',hubMessage)}}
function claimContract(id){const c=CONTRACTS.find(c=>c.id===id);if(!c||field.contracts.includes(id)||!c.ok())return;field.contracts.push(id);wallet.balance=Math.min(1000000000,wallet.balance+c.reward);saveField();hubMessage=`${c.name} / 金币 +${c.reward}`;renderHub()}
