function rememberFieldStory(){if(V.route!=='story'||S.mode!=='play'||!S.completedMain)return;let dirty=false;if(!X.storyRemembered){X.storyRemembered=true;field.storyRuns++;for(let i=0;i<12;i++)if(!field.seen.includes(String(i)))field.seen.push(String(i));dirty=true}if(S.bossWon&&!X.bossRemembered){X.bossRemembered=true;field.bossWins++;dirty=true}if(dirty)saveField()}
function renderExtension(){rememberFieldStory();show('arcadeBtn',S.phase==='cover'&&!shopOpen&&!voyagePanel&&!hubOpen);show('extraMenuBtn',true);show('extraBadge',isExtra()&&S.phase==='running'&&!shopOpen&&!voyagePanel&&!hubOpen);set('streetTint','fill',field.nightTint===1?'#64d9b7':'#d19b57');set('streetTint','opacity',field.nightTint===0?0:.07);show('secretHotspots',S.phase==='cover'&&!hubOpen&&!shopOpen&&!voyagePanel);set('secretLetter','opacity',reduced?1:.64+Math.sin(idle*1.8)*.22);if(hubOpen){show('voyageBtn',false);show('archiveBtn',false);show('quickMenuBtn',false);show('voyageHUD',false);show('cashOutBtn',false)}if(!isExtra())return;show('voyageHUD',false);show('perfectBadge',false);if(S.phase==='running'){text('extraBadgeText',ROUTES[V.route].name+(V.route==='daily'?' / 原装公平':V.route==='courier'?' / 杯架 '+X.bag+' / 3':V.route==='wildrun'?' / 耐心 '+V.life+' / 3':''));text('chapterText',ROUTES[V.route].name);text('timerText',ROUTES[V.route].name+' / '+Math.floor(S.t)+(Number.isFinite(runDuration())?' : '+runDuration():' 秒'));text('equippedText',V.route==='daily'?'公平挑战 / 统一无技能':V.route==='tutorial'?'上手练习 / 统一原装':playSkill()?CATALOG.skills.find(c=>c.id===playSkill())?.name:'原装 / 无技能');text('subtitleLine',V.route==='courier'?`下一站 ${Math.max(0,Math.ceil(X.station*18-S.t))} 秒 / 杯架 ${X.bag} / 3 / 受击丢一杯`:V.route==='daily'?'同一天同一条街 / 统一无技能，成绩只存在本机':V.route==='tutorial'?S.t<8?'先按跳跃 / 再按一次是二段跳':S.t<18?'试试冲刺 / 能把前面的通知撞散':'练习咖啡已备好 / 按中间大招':'三格耐心 / 无自动盾，无金章；可主动收工');text('hintText',V.route==='wildrun'?'夜航菜单 → 地图/新支线 → 本局主动收工':'左跳 · 右冲 · 六杯咖啡开大招');set('progressFill','width',(mobile?640:1200)*Math.min(1,S.t/(Number.isFinite(runDuration())?runDuration():180)))}if(S.phase==='ending')text('ticketHint',V.route==='tutorial'?'练习不赚金币 / 正式成绩未动':`本局金币 +${S.runCoins} · 钱包 ${fmt(wallet.balance)} / 独立支线票根`)}
function extensionLayout(){const W=mobile?720:1280;pos('arcadeBtn',mobile?48:564,mobile?674:compact?421:544);buttonSize('arcadeBtn',mobile?608:compact?240:300,mobile?62:60);attr($('arcadeBtn').querySelector('text'),'font-size',mobile?24:22);pos('extraMenuBtn',30,mobile?1062:compact?89:686);buttonSize('extraMenuBtn',mobile?608:1000,mobile?62:compact?48:54);attr($('extraMenuBtn').querySelector('text'),'font-size',mobile?24:22);pos('extraBadge',mobile?26:compact?420:28,mobile?246:compact?104:150);set('extraBadgeBG','width',mobile?620:470);set('extraBadgeBG','height',mobile?78:compact?72:64);set('extraBadgeText','x',mobile?24:22);set('extraBadgeText','y',mobile?52:compact?48:44);set('extraBadgeText','font-size',mobile?34:compact?33:26);set('streetTint','width',W);set('streetTint','height',mobile?810:compact?500:710);set('secretMoon','transform',mobile?'translate(-353,-104)':compact?'translate(22,100)':'translate(22,11)');set('secretCat','transform',mobile?'translate(0,180)':compact?'translate(480,0)':'translate(0,0)');set('secretLetter','transform',mobile?'translate(0,180)':compact?'translate(0,55)':'translate(0,0)');if(mobile)set('timerText','y',1333);if(hubOpen)hubLayout()}
const SECRET_LINES={moon:['月亮没回消息','它也在免打扰。'],cat:['猫说今天不上班','我：你也没上过啊。'],coffee:['冰美式不加糖','群里的话已经够甜了。'],letter:['寄给没有工位的我','收件地址：自由。'],whale:['鲸说不必解释','懂了。彳亍，兜风。']};
function findStreetSecret(id){if(S.phase!=='cover'||hubOpen||shopOpen||voyagePanel)return;const line=SECRET_LINES[id];if(!line)return;if(!field.secrets.includes(id)){field.secrets.push(id);saveField()}text('coverLine1',line[0]);text('coverLine2',line[1]);text('hintText','街头暗号 '+field.secrets.length+' / 5 · 自由手账里会记着');beep(640,.12,'sine',.017)}
function extraTicket(){return `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="660" viewBox="0 0 1000 660"><rect width="1000" height="660" rx="28" fill="#0c2032"/><path d="M35 92H965M35 541H965" stroke="#739e95" stroke-dasharray="6 9"/><g font-family="system-ui,sans-serif"><text x="45" y="61" fill="#a7ebcb" font-size="24">NIGHT OFF / 野狗逃班 5.1 合流</text><text x="45" y="159" fill="#ffe1a6" font-size="45">${escapeXML(S.ending)}</text><text x="45" y="219" fill="#b9d4d3" font-size="25">${escapeXML(ROUTES[V.route].name)} / ${escapeXML(X.date)}</text><text x="45" y="285" fill="#dce9d6" font-size="26">${Math.floor(S.t)}秒 / ${extraScore()}分 / 金币 +${S.runCoins}</text><text x="45" y="338" fill="#a8d2c5" font-size="24">冰美式 ${S.coffee} / 送达 ${X.delivered}杯 / 被催 ${S.hits}次</text><text x="45" y="415" fill="#c8c6e7" font-size="23">${V.route==='daily'?'公平规则：统一无技能 / 路线种子 '+X.seed:V.route==='tutorial'?'练习不计钱包和正式成绩':'一路自由，不用申请。'}</text><text x="45" y="605" fill="#86aba9" font-size="21">本机生成，不上传数据 / ONE WAY · 不返工</text></g></svg>`}
function initExtension(){bind('arcadeBtn',()=>toggleHub());bind('extraMenuBtn',()=>toggleHub());bind('hubCloseBtn',()=>toggleHub(false));bind('hubNativeBtn',()=>nativeMenu());for(const[t,id]of [['routes','routeTab'],['map','mapTab'],['journal','journalTab'],['settings','settingsTab']])bind(id,()=>setHubTab(t));for(const e of ['pointerdown','click'])$('arcadePanel').addEventListener(e,ev=>ev.stopPropagation());for(const[id,key]of [['secretMoon','moon'],['secretCat','cat'],['secretCoffee','coffee'],['secretLetter','letter'],['secretWhale','whale']])bind(id,()=>findStreetSecret(key));window.addEventListener('keydown',e=>{if(!hubOpen)return;if(e.key==='Escape'){e.preventDefault();toggleHub(false)}if(e.key==='Tab'){e.preventDefault();const all=[...$('arcadePanel').querySelectorAll('[tabindex="0"]')].filter(el=>!el.closest('.hide')),i=all.indexOf(document.activeElement);all[(i+(e.shiftKey?-1:1)+all.length)%all.length]?.focus()}});if(new URLSearchParams(location.search).has('qa'))window.__extraQA=Object.freeze({start:playRoute,field:()=>JSON.parse(JSON.stringify(field)),settle:()=>{if(V.route==='wildrun'&&S.phase==='running')finishExtra('cashout')}})}

