function playMap(id){if(!NIGHTS[id])return;pendingMapResume=mapStore.checkpoint?.id===id?{...mapStore.checkpoint}:null;playRoute('map'+id);if(pendingMapResume){const c=pendingMapResume;pendingMapResume=null;Object.assign(M,{coins:c.coins,tokens:c.tokens,routePoints:c.routePoints,skill:c.skill,skin:c.skin,runId:c.runId});V.gear=c.skill?'equipped':'stock';Object.assign(S,{guard:c.skill==='shield'?1:0,t:NIGHTS[id].seconds,coffee:c.coffee,hits:c.hits,smashed:c.smashed,maxCombo:c.maxCombo,runCoins:c.coins});applySkin();mapGate(false)}}
function beginMap(){clearMapFight();M=mapDefaults();if(!isMap())return;const n=night();Object.assign(M,{id:n.id,skill:wallet.skill,skin:wallet.skin,runId:dateKey()+'-'+Date.now()+'-'+Math.random().toString(36).slice(2,9)});V.gear=M.skill?'equipped':'stock';V.life=4;seed=daySeed('twelve-night-'+n.id);S.spawn=.75;S.chapter=0}
function mapSpeed(){const n=night(),wind=n.id===6?1+(Math.floor(S.t/8)%2)*.12:n.id===7?1+(Math.floor(S.t/10)%2?-.06:.08):n.id===8?1+Math.sin(S.t*.5)*.055:1;return n.speed*wind}
function spawnMap(){const n=night(),k=S.spawnIndex++,a=n.pattern[k%n.pattern.length],next=n.pattern[(k+1)%n.pattern.length],base=mobile?930:1400;spawnOne(a[0]==='coffee'?'coffee':'m'+n.id+a[0],a[1],base);if(k%2===0)for(let i=0;i<3;i++)spawnOne('coin',[-54,-105,-54][i],base+95+i*55);const ground=a[1]===0&&a[0]!=='coffee';S.safeGap=ground&&next[1]<-150?1.8:0}
function mapDecorate(o){if(!isMap()||!o.type.startsWith('m'))return;o.kind=o.type.replace(/^m\d+/,'');o.token=o.kind==='token';o.baseY=o.y;o.movePhase=(S.spawnIndex%3)*1.4;o.ghost=false}
function mapObjects(dt){if(!isMap())return;M.worldT+=dt;for(const o of items){if(o.done||!o.kind)continue;const t=M.worldT+o.movePhase;if(o.kind==='swing')o.y=o.baseY+Math.sin(t*2.2)*34;if(o.kind==='bubble')o.y=o.baseY+Math.sin(t*2.6)*40;if(o.kind==='leaf')o.y=o.baseY+Math.sin(t*1.8)*57;if(o.kind==='wheel')o.x-=Math.max(0,Math.sin(t*2))*90*dt;if(o.kind==='gate'){o.ghost=Math.floor(t/2)%2===0;attr(o.el,'opacity',o.ghost?.33:1);attr(o.el,'data-open',o.ghost)}}}
function mapToken(o){o.done=true;M.tokens++;const n=night();if(n.effect==='energy')gainEnergy(.7);else if(n.effect==='repair'&&M.tokens%3===0){S.guard=Math.min(1,S.guard+1);toast('备用件齐了 / 纸盾 +1',n.color)}else if(n.effect==='delivery'){M.bag++;if(M.bag>=3){M.bag=0;M.delivered++;gainEnergy(1);toast(n.id===2?'三杯交货 / 反击充能':'早点交篮 / 反击充能',n.color)}}else combo();puff(o.x,o.y-35,5,n.color);toast(n.goal+' '+M.tokens,n.color)}
function mapAward(amount){if(!isMap())return false;if(S.mode==='play'&&!V.finished&&!M.settled&&!mapStore.wins.includes(M.id)){amount=Math.max(0,Math.floor(amount));const add=Math.min(amount,Math.max(0,180-M.coins));M.coins+=add;S.runCoins=M.coins}return true}
function mapDamage(){if(!isMap())return;M.life=Math.max(0,M.life-1);V.life=M.life;if(night().effect==='delivery')M.bag=Math.max(0,M.bag-1)}
function tickMap(){if(S.phase!=='running'||V.finished)return;V.elapsed=S.t;if(M.life<=0){mapSettle(false,'route');return}if(S.t>=runDuration())mapGate()}
function mapGate(write=true){if(M.settled)return;M.checkpoint=true;M.routeHits=S.hits;if(write)M.routePoints=score();clearWorld();Object.assign(S,{phase:'bossGate',paused:false,y:0,vy:0,jumps:0,dash:0,offset:0,freedom:0,chrono:0,inv:0,cool:0});if(write){mapStore.checkpoint={id:M.id,createdAt:Date.now(),skill:M.skill,skin:M.skin,coins:M.coins,tokens:M.tokens,coffee:S.coffee,hits:S.hits,smashed:S.smashed,maxCombo:S.maxCombo,routePoints:M.routePoints,runId:M.runId};saveMaps()}for(const id of ['hud','skillHud','subtitle','perfectBadge','ending'])show(id,false);show('bossGate',true);show('bossResult',false);render()}
function clearMapFight(){mapProjectiles.forEach(o=>o.el.remove());mapProjectiles=[];for(const id of ['mapBossActor','mapBossWarnings','mapBossAttacks'])if($(id))$(id).replaceChildren()}
function mapBossStart(){if(!isMap()||!M.checkpoint||M.settled||shopOpen||hubOpen||voyagePanel)return;clearWorld();clearMapFight();shots.forEach(o=>o.el.remove());shots=[];const n=night();Object.assign(S,{phase:'boss',paused:false,y:0,vy:0,jumps:0,dash:0,cool:0,inv:0,freedom:0,energy:3,offset:0,chrono:0,guard:M.skill==='shield'?1:0,jumpBuffer:0,legendSerial:-1,orbitTick:0,paperTick:0,whaleTick:0});Object.assign(B,bossDefaults,{hp:n.hp,maxHP:n.hp,player:3,timer:2,state:'intro',stage:1});Object.assign(M,{attack:null,aims:[],events:[],openDamage:0,openShots:0,usedSuper:false});svg.classList.remove('paused');for(const id of ['bossGate','bossResult','ending','hud','perfectBadge'])show(id,false);for(const id of ['bossWorld','bossHud','bossCallout','skillHud','subtitle'])show(id,true);$('mapBossActor').appendChild(node('use',{href:'#guardianArt'+n.id}));last=performance.now();render()}
function mapNextAttack(){const n=night(),list=GUARDIANS[n.id][B.stage-1];M.attack=list[B.cycle%list.length];B.cycle++;B.state='telegraph';B.timer=1.45;B.elapsed=0;M.aims=M.attack.events.map(()=>({x:dogX()+17,y:GROUND+S.y-65,locked:false,hit:false,launched:false}));B.pattern=M.attack.name;M.events=M.attack.events.map(e=>({...e}));B.notice=''}
function mapShoot(power){if(S.phase!=='boss'||B.state==='intro'||B.state==='phaseChange')return;const cap=['orbit','leviathan','chrono'].includes(playSkill())?3:2;if(B.state!=='open'){B.blocked++;toast('等完这一轮 / 绿窗才反击',night().color);return}if(M.openShots>=cap)return;const p=Math.min(power,cap-M.openShots,cap-M.openDamage);M.openShots+=p;const el=node('path',{d:'M-16-6L20 0-16 6-7 0Z',fill:night().color,stroke:'#efffde','stroke-width':2});$('bossShots').appendChild(el);shots.push({el,x:dogX()+65,y:GROUND+S.y-78,power:p,life:1.5,serial:B.openSerial});B.notice=''}
function mapHit(power,serial){if(B.state!=='open'||serial!==B.openSerial)return;const cap=['orbit','leviathan','chrono'].includes(playSkill())?3:2,p=Math.min(power,cap-M.openDamage,B.hp);if(p<=0)return;M.openDamage+=p;B.hp-=p;B.landed++;gainEnergy(1);combo();toast('破绽命中 / -'+p,night().color);puff(mobile?650:915,410,8,night().color);if(B.hp<=0){B.won=true;S.phase='bossVictory';B.state='defeated';B.timer=2;S.inv=3;S.freedom=0;S.chrono=0;clearMapProjectiles()}else if(B.stage===1&&B.hp<=B.maxHP/2){B.stage=2;B.state='phaseChange';B.timer=2;S.inv=Math.max(.6,S.inv);clearMapProjectiles()}}
function clearMapProjectiles(){mapProjectiles.forEach(p=>p.el.remove());mapProjectiles=[]}
function mapBossDamage(){if(S.inv>0||S.dash>0||S.freedom>0||B.player<=0)return;if(consumeShield())return;B.player--;B.hits++;S.inv=1.25;toast('耐心 -1 / 看亮起的危险区','#ffc0c1');puff(dogX(),GROUND+S.y-65,8,'#f9acb5');if(B.player<=0)mapBossFail()}
function mapBossFail(){S.phase='bossResult';S.paused=false;S.freedom=0;S.chrono=0;S.dash=0;clearMapProjectiles();show('bossResult',true);for(const id of ['bossHud','bossCallout','skillHud','subtitle'])show(id,false);render()}
function launchMapAttack(e){const bx=mobile?650:915,p=node('g'),c=night().color;p.appendChild(e.kind==='wheel'?node('circle',{r:29,fill:'#273c4a',stroke:c,'stroke-width':6}):node('path',{d:e.kind==='orb'?'M-22 0Q-19-32 12-21L31 0 11 22Q-23 26-22 0Z':'M-38-8L30 0-38 8-16 0Z',fill:c,stroke:'#f4eed7','stroke-width':2}));$('mapBossAttacks').appendChild(p);mapProjectiles.push({el:p,kind:e.kind,x:bx,y:e.y,base:e.y,vx:(bx-317)/.92,age:0,life:1.35,done:false})}
function stepMapBoss(dt){if(S.paused||!['boss','bossVictory'].includes(S.phase))return;const worldDt=S.phase==='boss'?tickLegend(dt):dt;B.t+=worldDt;B.elapsed+=worldDt;for(const k of ['cool','dash','inv','toast','shake','comboTime','jumpBuffer','freedom'])S[k]=Math.max(0,S[k]-dt);updateDashMotion(dt);const wasAir=S.y<0;S.vy+=1600*dt;S.y+=S.vy*dt;if(S.y>=0){S.y=0;S.vy=0;S.jumps=0;if(wasAir){ripple(dogX());if(S.jumpBuffer>0)jumpCore()}}S.distance+=55*worldDt;updateFX(dt);B.timer-=worldDt;
 if(S.phase==='bossVictory'){if(B.timer<=0)mapSettle(true);return}if(B.t>200){mapBossFail();return}
 if(['intro','phaseChange'].includes(B.state)&&B.timer<=0)mapNextAttack();else if(B.state==='telegraph'&&B.timer<=0){B.state='active';B.elapsed=0;B.timer=M.attack.duration}else if(B.state==='active'){
  M.events.forEach((e,i)=>{if(S.phase!=='boss')return;const a=M.aims[i];if(e.kind==='lock'&&!a.locked&&B.elapsed>=e.t-.48){a.x=dogX()+17;a.y=GROUND+S.y-65;a.locked=true}if(['bolt','orb','wheel'].includes(e.kind)&&B.elapsed>=e.t&&!a.launched){a.launched=true;launchMapAttack(e)}if(B.elapsed<e.t||B.elapsed>=e.t+e.dur||a.hit)return;const cy=GROUND+S.y-65,hit=e.kind==='floor'?S.y>-89:e.kind==='high'?cy>292&&cy<447:e.kind==='lock'?Math.abs(cy-a.y)<56&&Math.abs(dogX()+17-a.x)<85:false;if(hit&&S.inv<=0&&S.dash<=0&&S.freedom<=0){a.hit=true;mapBossDamage()}});
  if(S.phase==='boss'&&B.timer<=0){B.state='open';B.timer=3.1;B.elapsed=0;B.openSerial++;M.openDamage=0;M.openShots=0;M.usedSuper=false;gainEnergy(1);S.cool=Math.min(S.cool,.16);clearMapProjectiles()}
 }else if(B.state==='open'&&B.timer<=0)mapNextAttack();
 const cy=GROUND+S.y-65;mapProjectiles=mapProjectiles.filter(p=>{p.age+=worldDt;p.x-=p.vx*worldDt;p.life-=worldDt;if(p.kind==='orb')p.y=p.base+Math.sin(p.age*5)*23;attr(p.el,'transform',`translate(${p.x},${p.y})${p.kind==='wheel'?` rotate(${p.age*300})`:''}`);if(Math.abs(p.x-(dogX()+17))<60&&Math.abs(p.y-cy)<61&&!p.done){if(S.dash>0||S.freedom>0){p.done=true;puff(p.x,p.y,4,night().color)}else if(S.inv<=0){p.done=true;mapBossDamage()}}if(p.life<=0||p.x<80||p.done){p.el.remove();return false}return true});
 const target=mobile?650:915;shots=shots.filter(o=>{o.life-=dt;o.x+=1000*dt;o.y+=(401-o.y)*Math.min(1,dt*6);attr(o.el,'transform',`translate(${o.x},${o.y})`);if(o.x>=target){mapHit(o.power,o.serial);o.el.remove();return false}if(o.life<=0){o.el.remove();return false}return true});
}
function mapSettle(won,reason='boss'){if(M.settled||V.finished)return;M.settled=true;const n=night(),key=n.id+':'+(M.skill?'equipped':'stock'),points=Math.max(0,(M.checkpoint?M.routePoints:score())+M.tokens*18+(won?500+Math.max(0,200-Math.floor(B.t)):0));let earned=0;if(won){if(!mapStore.wins.includes(n.id)){mapStore.wins.push(n.id);earned=n.reward+M.coins;mapStore.awards[String(n.id)]={amount:earned,runId:M.runId};wallet.balance=Math.min(1e9,wallet.balance+earned)}const r=mapStore.records[key]||{best:0,wins:0,time:200};r.best=Math.max(r.best,points);r.wins++;r.time=Math.min(r.time,Math.floor(B.t));mapStore.records[key]=r;if(mapStore.checkpoint?.id===n.id&&mapStore.checkpoint.runId===M.runId)mapStore.checkpoint=null;if(!field.seen.includes(String(n.id)))field.seen.push(String(n.id));unlockJourney('first')}saveMaps();V.finished=true;V.resultCoins=earned;V.reason=won?'victory':reason;clearWorld();clearMapFight();shots.forEach(o=>o.el.remove());shots=[];Object.assign(S,{phase:'ending',paused:false,freedom:0,chrono:0,dash:0,y:0,vy:0,offset:0,score:points,runCoins:earned,ending:won?n.name+' / 通行':'这条路，歇会再走'});svg.classList.remove('paused');for(const id of ['bossGate','bossResult','bossWorld','bossHud','bossCallout','hud','skillHud','subtitle','freedomBanner'])show(id,false);show('ending',true);text('endTitle',won?'第 '+(n.id+1)+' 夜 / 已通行':'耐心用完，路还在');text('endLine',won?n.boss+'已安静 / 风不用审批':reason==='route'?'地图没走完 / 拾币未入账，重跑不掉钱包':'Boss检查点保留 / 从地图可继续这场');text('endStats',`${n.goal} ${M.tokens} / 跑图受击 ${M.checkpoint?M.routeHits:S.hits} / 反击 ${B.landed}`);text('bestText',`${V.gear==='stock'?'原装':'装备'} · ${points}分 / 首胜 ${earned?'+'+earned+'币':'已领，不重复'}`);text('badgeText',`十二夜路 ${mapStore.wins.length} / 12 · 原夜航档案完整保留`);render()}
function mapSnapshot(){return isMap()?{...M,attack:M.attack?{...M.attack}:null,aims:M.aims.map(a=>({...a})),events:M.events.map(e=>({...e})),projectiles:mapProjectiles.map(p=>({kind:p.kind,x:p.x,y:p.y,vx:p.vx})),wins:[...mapStore.wins],checkpoint:mapStore.checkpoint?{...mapStore.checkpoint}:null,records:JSON.parse(JSON.stringify(mapStore.records)),scene:mapSceneKey}:null}

const SCENE_ROUTE={cruise:8,contract:1,endless:6,dojo:4,courier:2,daily:5,wildrun:7,tutorial:0};
const LIVE_SKY=['#102737','#221c38','#183129','#26273c','#213039','#142940','#1a2b3c','#222244','#1a3a49','#1d3037','#1b2d44','#736967'];
const lookSkin=()=>isMap()&&S.phase!=='cover'?M.skin:wallet.skin;
function sceneNight(){return isMap()?night().id:Object.hasOwn(SCENE_ROUTE,V.route)&&S.phase!=='cover'?SCENE_ROUTE[V.route]:-1}
function renderNightScene(){const id=sceneNight(),on=id>=0;show('nightLiveBG',on);show('nightLiveFG',on);if(!on){mapSceneKey='story';return}mapSceneKey=String(id);if($('nightLiveBG').getAttribute('data-night')!==String(id)){attr($('nightLiveBG'),'data-night',id);set('liveNightSky','fill',LIVE_SKY[id]);for(const layer of ['Far','Mid','Front'])for(const k of ['A','B'])set('live'+layer+k,'href','#night'+layer+id)}const d=S.distance;for(const[layer,speed]of [['Far',.12],['Mid',.39],['Front',.86]]){const shift=-(d*speed%1280);for(const[k,off]of [['A',0],['B',1280]])set('live'+layer+k,'transform',`translate(${shift+off},0)`)}set('nightRoad','fill',id===11?'#566560':id===8?'#233e46':'#162d38');set('nightWeather','opacity',reduced?0:id===0?.16:id===8?.08:0);set('nightWeather','transform',`translate(${-S.t*40%50},${S.t*200%140})`);set('rain','opacity',id===0&&!reduced?.22:0);set('drone','opacity',0);set('streetCat','opacity',0);set('overpass','opacity',0);set('dawn','opacity',0);set('sunrise','opacity',0);set('nightGlow','opacity',id===11?.35:id===10?.15:.06)}
function renderMapBoss(){const visible=['boss','bossVictory','bossResult'].includes(S.phase);show('bossWorld',visible);show('bossMachine',false);show('bossShadow',false);show('bossHud',['boss','bossVictory'].includes(S.phase));show('bossCallout',['boss','bossVictory'].includes(S.phase));show('mapBossActor',visible);show('mapBossWarnings',visible);show('mapBossAttacks',visible);show('bossWarnings',false);show('bossWaves',false);show('beamImpact',false);show('bossBurst',false);if(!visible)return;const n=night(),bx=mobile?650:915;set('mapBossActor','transform',`translate(${bx},${401+(reduced?0:Math.sin(B.t*1.6)*7)}) scale(${mobile?.72:.94})`);set('mapBossActor','opacity',B.state==='defeated'?Math.max(.15,B.timer/2):1);text('bossName',n.boss);text('bossHPText',B.hp+' / '+B.maxHP);set('bossHPBar','width',(mobile?430:600)*B.hp/B.maxHP);text('bossHeartText','耐心 '+('◆'.repeat(B.player))+('◇'.repeat(3-B.player))+' '+B.player+'/3');text('bossStageText',B.stage===1?'第一形态':'第二形态');let msg=B.state==='intro'?'看预警 / 攻击结束，绿窗冲刺':B.state==='telegraph'?M.attack.name+' / 先看亮区':B.state==='active'?M.attack.name+' / 不抢跳':B.state==='open'?'破绽 / 冲刺反击 · 每窗有限额':B.state==='phaseChange'?'第二形态 / 攻击重新编排':B.state==='defeated'?'道路放行 / 首胜奖励只领一次':'检查点保留';text('bossCalloutText',B.notice||msg);set('bossCalloutText','fill',B.state==='open'?'#b8ffe0':n.color);set('bossCalloutBg','stroke',B.state==='open'?'#b8ffe0':n.color);text('subtitleLine',B.state==='open'?'冲刺发出纸反击 / 六杯可开大，不能一窗秒掉':M.attack?M.attack.events.map(e=>e.kind==='floor'?'地面亮→跳':e.kind==='high'?'高空亮→站':e.kind==='lock'?'锁定位置→再移动':'飞弹到身前→跳或冲').filter((v,i,a)=>a.indexOf(v)===i).join(' · '):'三格耐心 / 失败只重试Boss，不用再跑图');renderMapWarnings()}
function renderMapWarnings(){const g=$('mapBossWarnings');g.replaceChildren();if(!M.attack||!['telegraph','active'].includes(B.state))return;const warning=B.state==='telegraph',now=warning?-1:B.elapsed,W=mobile?760:1160;M.events.forEach((e,i)=>{const a=M.aims[i],until=e.t-now,active=!warning&&until<=0&&until>-e.dur;if(!warning&&(until> .6||until<=-e.dur))return;const color=active?'#ffae9b':e.kind==='high'?'#d5b1f3':night().color,opacity=active?.36:.12;if(e.kind==='floor'||e.kind==='high'){const high=e.kind==='high',y=high?292:406,h=high?155:154;g.appendChild(node('rect',{x:145,y,width:W-145,height:h,fill:color,'fill-opacity':opacity,stroke:color,'stroke-width':active?4:2,'stroke-dasharray':active?'':'12 9'}));const t=node('text',{x:mobile?498:775,y:high?322:464,'text-anchor':'middle',fill:color,'font-size':21});t.textContent=high?'上方危险 / 站地面':'地面危险 / 准备跳';g.appendChild(t)}else if(e.kind==='lock'){const x=a.locked?a.x:dogX()+17,y=a.locked?a.y:GROUND+S.y-65;g.appendChild(node('rect',{x:x-85,y:y-56,width:170,height:112,rx:13,fill:color,'fill-opacity':opacity,stroke:color,'stroke-width':3,'stroke-dasharray':active?'':'8 6'}));const t=node('text',{x:mobile?508:760,y:350,fill:color,'font-size':21,'text-anchor':'middle'});t.textContent=a.locked?'位置已锁 / 现在移动':'追踪落点 / 等它锁定';g.appendChild(t)}else if(warning||until>0){const y=e.y;if(e.kind==='orb')g.appendChild(node('rect',{x:220,y:y-23,width:(mobile?650:915)-220,height:46,fill:color,'fill-opacity':.09,stroke:color,'stroke-dasharray':'10 7'}));g.appendChild(node('path',{d:`M${mobile?640:920} ${y}H220m18-14-18 14 18 14`,stroke:color,'stroke-width':3,fill:'none','stroke-dasharray':'15 10'}));const t=node('text',{x:mobile?530:810,y:y-21,fill:color,'font-size':18});t.textContent=e.kind==='wheel'?'滚轮 / 跳过去':e.kind==='orb'?'浮弹 / 看高度':'飞弹 / 留意轨迹';g.appendChild(t)}})}

function drawPlayableMap(g){const n=NIGHTS[mapIndex],w=mobile?632:1156,clear=mapStore.wins.includes(n.id),resume=mapStore.checkpoint?.id===n.id;labelAt(g,`${n.id+1} / 12 · ${n.name}`,22,42,mobile?30:32,'#ffe3b1',800);const y=mobile?75:compact?60:73,aw=mobile?588:compact?480:603,ah=mobile?310:compact?202:310;g.appendChild(node('use',{href:'#postcard'+n.id,x:22,y,width:aw,height:ah}));if(!mobile){const x=compact?527:669;g.appendChild(node('use',{href:'#guardianArt'+n.id,transform:`translate(${x+183},${compact?142:192}) scale(${compact?.5:.62})`}));labelAt(g,n.boss,x,compact?232:299,compact?23:26,n.color,800);labelAt(g,n.seconds+'秒独立跑图 → 两形态守夜者',x,compact?264:336,compact?18:21);labelAt(g,clear?'首胜已领 / 重打练习，不重复造币':'首胜 '+n.reward+'币 + 本图托管拾币',x,compact?291:369,18,'#afd5cb')}const by=mobile?706:compact?309:390;svgButton(g,'mapPrevBtn','← 前一站',22,by,mobile?271:220,59,()=>{mapIndex=(mapIndex+11)%12;routeConfirm='';renderHubBody()});svgButton(g,'mapNextBtn','后一站 →',mobile?337:w-242,by,mobile?271:220,59,()=>{mapIndex=(mapIndex+1)%12;routeConfirm='';renderHubBody()});svgButton(g,'postcardSaveBtn','保存明信片',mobile?181:compact?470:468,mobile?778:compact?309:390,mobile?270:220,59,savePostcard,'#caa972');const gy=mobile?615:compact?240:461;svgButton(g,'mapPlayBtn',resume?'继续本关Boss →':clear?'重游 / 已通关 →':'进入可玩关卡 →',mobile?22:compact?22:22,gy,mobile?588:compact?480:580,mobile?72:57,()=>selectPlayableMap(n.id),n.color);if(mobile){labelAt(g,n.boss,22,419,29,n.color,800);labelAt(g,`${n.seconds}秒跑图 · 四格耐心 / Boss三格`,22,454,21);labelAt(g,clear?'首胜已领 / 重游不重复造币':'首胜 '+n.reward+'币 + 本图拾币（首胜才入账）',22,490,19,'#afd5cb');const chars=Array.from(n.story);for(let k=0;k<chars.length;k+=27)labelAt(g,chars.slice(k,k+27).join(''),22,535+Math.floor(k/27)*29,20,'#b9cfce')}else if(!compact)labelAt(g,n.story,635,482,18,'#b9cfce')}
function selectPlayableMap(id){const key='map'+id;if(['running','boss','bossVictory','bossGate','bossResult'].includes(S.phase)&&routeConfirm!==key){routeConfirm=key;hubMessage='再点确认 / 离开当前局；本图Boss检查点会保留';text('hubMessage',hubMessage);return}toggleHub(false);playMap(id)}
function renderMaps(){renderNightScene();if(!isMap()){for(const id of ['mapBossActor','mapBossWarnings','mapBossAttacks'])show(id,false);show('bossMachine',true);show('bossShadow',true);show('bossWarnings',true);show('bossWaves',true);text('bossName','终审官 / 永不下班');text('gateTitle','终审官 · 永不下班');$('fightBtn').querySelector('text').textContent='拆掉审批机 →';text('bossResultKicker','挑战结束 / 主关完美成绩保留');text('gateLine1','主关完美成绩已保存。额外一战，三格耐心。');text('gateLine2','先躲预警 / 护盾打开再冲刺反击');text('gateFoot','可以不打。自由不是必须证明自己。');return}
 show('voyageHUD',false);show('extraBadge',S.phase==='running'&&!hubOpen&&!shopOpen&&!voyagePanel);show('perfectBadge',false);show('cashOutBtn',false);text('equippedText',M.skill?CATALOG.skills.find(c=>c.id===M.skill)?.name:'原装 / 无技能');text('coinText','托管 '+M.coins);text('timerText',['boss','bossVictory','bossResult'].includes(S.phase)?`守夜者 / ${Math.floor(B.t)}秒`:`地图 / ${Math.floor(S.t)}:${night().seconds}`);text('hintText',S.phase==='boss'?'先躲亮区 / 绿窗才反击 / 单窗有伤害限额':'左跳 · 右冲 · 六杯开大招');if(S.phase==='running'){text('extraBadgeText',`${night().name} · 耐心 ${'◆'.repeat(M.life)}${'◇'.repeat(4-M.life)} ${M.life}/4`);text('chapterText',`${M.id+1} / ${night().name}`);text('timerText',Math.floor(S.t)+' / '+night().seconds+'秒 → Boss');text('subtitleLine',night().story);text('hintText',night().goal+' '+M.tokens+' / 拾币首胜才入钱包 / 左跳右冲');set('progressFill','width',(mobile?640:1200)*S.t/night().seconds)}if(S.phase==='bossGate'){text('gateKicker',`第 ${M.id+1} 夜 / 地图已走完 · 检查点已存`);text('gateTitle',night().boss);$('fightBtn').querySelector('text').textContent='挑战守夜者 →';attr($('fightBtn'),'aria-label','挑战 '+night().boss);set('gateTitle','font-size',mobile?41:compact?48:55);text('gateLine1','三格耐心 / 失败只重试这只Boss');text('gateLine2','看危险区，等绿窗 / 原装能打，技能只是辅助');text('gateFoot',`托管 ${M.coins}币 · ${night().goal} ${M.tokens} / 装备与皮肤锁至本关结束`)}if(S.phase==='bossResult'){text('bossResultKicker','守夜者挑战 / 本关检查点保留');text('bossResultTitle','耐心用完，检查点还在');set('bossResultTitle','font-size',mobile?38:55);text('bossResultLine','只重试这一战 / 原图不用再跑，奖励还没结算');text('bossResultStats',night().boss+` / 剩 ${B.hp} 格 · 坚持 ${Math.floor(B.t)}秒`);text('bossResultFoot','也能先回封面 / 地图页继续本关Boss')}if(S.phase==='ending')text('ticketHint',`本关金币 +${V.resultCoins} · 钱包 ${fmt(wallet.balance)} / 十二夜路 ${mapStore.wins.length}/12`);if(['boss','bossVictory','bossResult'].includes(S.phase))renderMapBoss()}
function mapTicket(){return `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="660" viewBox="0 0 1000 660"><rect width="1000" height="660" rx="26" fill="#102d3b"/><g font-family="system-ui,sans-serif"><text x="45" y="65" fill="#bcebd2" font-size="25">野狗逃班 5.2 / 十二夜路</text><text x="45" y="156" fill="#ffe0af" font-size="48">${escapeXML(night().name)}</text><text x="45" y="220" fill="#c6dfd5" font-size="30">${escapeXML(night().boss)} / ${V.reason==='victory'?'已通行':'暂时收工'}</text><text x="45" y="299" fill="#d8e6d3" font-size="27">${escapeXML(night().goal)} ${M.tokens} / 反击 ${B.landed} / 首胜结算 +${V.resultCoins}</text><text x="45" y="360" fill="#b7d8d3" font-size="25">${escapeXML(CATALOG.skins.find(c=>c.id===M.skin).name)} / ${escapeXML(CATALOG.skills.find(c=>c.id===M.skill)?.name||'原装')}</text><text x="45" y="449" fill="#9ac5bb" font-size="24">十二夜路 ${mapStore.wins.length} / 12 / 同图首胜只领一次</text><text x="45" y="588" fill="#789c9f" font-size="22">ONE WAY / 本机生成，不上传数据 / ${escapeXML(dateKey())}</text></g></svg>`}
function initMaps(){if(new URLSearchParams(location.search).has('qa'))window.__mapsQA=Object.freeze({start:playMap,get:mapSnapshot,store:()=>JSON.parse(JSON.stringify(mapStore)),catalog:()=>NIGHTS.map(n=>({...n})),boss:mapBossStart});}

// Same-wallet cross-page serialization. Local gains are deltas; spending is never merged by max(balance).
let persistBase=null,persistQueue=Promise.resolve(),persistPending=0;
const plain=x=>JSON.parse(JSON.stringify(x)),same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
try{persistBase=JSON.parse(localStorage.getItem('nightOffProgressV4')||'null')}catch(e){storageOK=false}
if(!persistBase||typeof persistBase!=='object')persistBase=plain(wallet);
function mergeSave(old,next,live,path=''){
 if(same(old,next))return live===undefined?(next===undefined?undefined:plain(next)):live;
 if(Array.isArray(next)){const current=Array.isArray(live)?live:[];if(['ownedSkins','ownedSkills','achievements','secrets','seen','contracts'].includes(path.split('.').at(-1))||path==='voyage.extras.maps.wins')return [...new Set([...current,...next])];return plain(next)}
 if(next&&typeof next==='object'){
  const result={...(live&&typeof live==='object'?live:{})};for(const[k,v]of Object.entries(next)){const p=path?path+'.'+k:k;result[k]=mergeSave(old?.[k],v,result[k],p)}return result
 }
 if(typeof next==='number'){
  if(path==='balance')return bounded((Number(live)||0)+next-(Number(old)||0),0,1e9);
  const k=path.split('.').at(-1);if(['runs','wins','storyRuns','bossWins','delivered'].includes(k))return Math.max(0,(Number(live)||0)+next-(Number(old)||0));
  if(['score','best','endlessBest'].includes(k))return Math.max(Number(live)||0,next);
  if(k==='time'&&path.startsWith('voyage.extras.maps.records.'))return live===undefined?next:Math.min(Number(live)||200,next);
  if(k==='time'||k==='t')return Math.max(Number(live)||0,next);
 }
 if(path==='voyage.devClaimed')return live===true||next===true;
 return next
}
function persistenceWrite(old,next){let live=null;try{live=JSON.parse(localStorage.getItem('nightOffProgressV4')||'null')}catch(e){storageOK=false}if(!live||typeof live!=='object')live=plain(old);
 const oldMaps=plain(old.voyage?.extras?.maps||{}),newMaps=plain(next.voyage?.extras?.maps||{}),liveMaps=plain(live.voyage?.extras?.maps||{}),merged=mergeSave(old,next,plain(live));let duplicate=0;
 if(old.voyage?.devClaimed!==true&&next.voyage?.devClaimed===true&&live.voyage?.devClaimed===true)duplicate+=Math.min(100000,Math.max(0,next.balance-old.balance));
 const added=(newMaps?.wins||[]).filter(i=>!(oldMaps?.wins||[]).includes(i));for(const i of added)if((liveMaps?.wins||[]).includes(i)){const entry=newMaps?.awards?.[String(i)];duplicate+=Math.min(entry?.amount||0,Math.max(0,next.balance-old.balance))}
 merged.balance=bounded((Number(live.balance)||0)+(Number(next.balance)||0)-(Number(old.balance)||0)-duplicate,0,1e9);
 if(newMaps&&merged.voyage?.extras?.maps){const dst=merged.voyage.extras.maps,c=newMaps.checkpoint,prev=oldMaps?.checkpoint,current=liveMaps?.checkpoint;if(same(c,prev))dst.checkpoint=current??c??null;else if(!c&&current&&prev?.runId!==current.runId)dst.checkpoint=current;else if(c&&current&&c.runId!==current.runId&&(c.createdAt||0)<(current.createdAt||0))dst.checkpoint=current;else dst.checkpoint=c??null}
 try{localStorage.setItem('nightOffProgressV4',JSON.stringify(merged));storageOK=true}catch(e){storageOK=false;return plain(next)}
 if(duplicate){if(isMap()&&M.settled){S.runCoins=Math.max(0,S.runCoins-duplicate);V.resultCoins=Math.max(0,V.resultCoins-duplicate)}toast('同存档已经领过 / 不重复发米','#c4ddbe')}return merged
}
function saveWallet(){const old=plain(persistBase||wallet),next=plain(wallet);persistBase=next;persistPending++;
 const work=()=>{const out=persistenceWrite(old,next);persistPending--;if(persistPending===0){wallet.balance=out.balance;persistBase.balance=out.balance;journey.devClaimed=journey.devClaimed||out.voyage?.devClaimed===true;persistBase.voyage.devClaimed=journey.devClaimed;if(!storageOK&&voyagePanel==='dev'&&journey.devClaimed)pinMessage='已领取 / 存储受限，仅本页有效';for(const i of out.voyage?.extras?.maps?.wins||[])if(NIGHTS[i]&&!mapStore.wins.includes(i))mapStore.wins.push(i);render()}return out};
 if(navigator.locks?.request){persistQueue=persistQueue.catch(()=>{}).then(()=>navigator.locks.request('nightOffProgressV4-write',work)).catch(()=>{storageOK=false;persistPending=Math.max(0,persistPending-1)});window.__nightPersistence=persistQueue}else{work();persistQueue=Promise.resolve();window.__nightPersistence=persistQueue}return persistQueue
}
window.addEventListener('storage',e=>{if(e.key!=='nightOffProgressV4'||persistPending)return;try{const raw=JSON.parse(e.newValue||'null');if(!raw||typeof raw!=='object')return;wallet.balance=bounded(raw.balance,0,1e9);wallet.ownedSkins=[...new Set(['original',...wallet.ownedSkins,...(raw.ownedSkins||[]).filter(i=>CATALOG.skins.some(c=>c.id===i))])];wallet.ownedSkills=[...new Set([...wallet.ownedSkills,...(raw.ownedSkills||[]).filter(i=>CATALOG.skills.some(c=>c.id===i))])];journey.devClaimed=journey.devClaimed||raw.voyage?.devClaimed===true;const mp=raw.voyage?.extras?.maps;if(mp){for(const i of Array.isArray(mp.wins)?mp.wins:[])if(Number.isInteger(i)&&NIGHTS[i]&&!mapStore.wins.includes(i))mapStore.wins.push(i);mapStore.checkpoint=mp.checkpoint??null}persistBase.balance=wallet.balance;persistBase.ownedSkins=[...wallet.ownedSkins];persistBase.ownedSkills=[...wallet.ownedSkills];persistBase.voyage.devClaimed=journey.devClaimed;if(!persistBase.voyage.extras)persistBase.voyage.extras={};if(!persistBase.voyage.extras.maps)persistBase.voyage.extras.maps={};persistBase.voyage.extras.maps.checkpoint=plain(raw.voyage?.extras?.maps?.checkpoint??null);render()}catch(x){}});

const BALANCE_COPY={wind:{price:45,desc:'冲刺142 / 冷却2.7秒',detail:'冲刺位移118→142；跑图冷却2.7秒，Boss1.2秒。大招3.8秒。单槽，不能叠加。'},magnet:{price:65,desc:'近距吸币 / 顺手捞杯',detail:'金币吸附140，咖啡吸附85。没有自动破障或无敌，不改变大招。'},shield:{price:80,desc:'一枚纸盾 / 首次免伤',detail:'开局免伤一次；Boss每次重试补一盾，不叠层。单槽，不与其他技能叠加。'},rail:{price:800,desc:'手动雷弧 / 最多穿三障',detail:'冲刺真实雷弧，最多穿三障，沿途收币；跑图冷却2.6秒、Boss1.6秒且反击1伤。每窗最多2伤。雷弧破障不回能。'},orbit:{price:1800,desc:'纸护耗1杯 / 2.1秒间隔',detail:'纸护范围100、每2.1秒拦一障且耗1杯能量；吸附135。Boss取消自动纸，主动大招双纸；每窗最多3伤。纸护破障不回能，不能挂机无敌。'},leviathan:{price:3600,desc:'鲸落480 / 4.4秒鲸息',detail:'六杯开鲸：首拍480范围；鲸息4.4秒，每1秒扫前方180。Boss大招2伤、每窗最多3伤。鲸破障不回能，仍需捡咖啡。'},chrono:{price:9800,desc:'2.4秒时停 / 有限反击',detail:'六杯时停2.4秒，玩家可跳冲；时停冲刺冷却1.4秒。Boss闭盾仍得等，每绿窗最多3伤，不能冻窗秒杀。'}};
